    }

    /**
     * Processes the incoming OTLP metric data contained in the provided {@link JsonObject} message.
     * <p>
     * This method performs the following steps:
     * <ul>
     *     <li>Parses binary metric data from the message.</li>
     *     <li>Extracts metadata such as event source and object ID.</li>
     *     <li>Iterates through each {@code ResourceMetrics} object in the data.</li>
     *     <li>Extracts resource attributes to determine the service name.</li>
     *     <li>Sends test metric events if running in a test environment.</li>
     *     <li>Iterates over the metrics and processes each individually via {@code processMetric}.</li>
     *     <li>Dumps the processed metrics and logs processing time.</li>
     * </ul>
     * All resources are cleared after processing each resource metric to ensure no state leakage.
     * Errors during processing are logged but do not interrupt the loop.
     *
     * @param message a {@link JsonObject} containing the OTLP-encoded metric data under the key {@code EVENT},
     *                along with metadata such as {@code EVENT_SOURCE} and {@code OBJECT_ID}.
     */
    private void process(JsonObject message)
    {
        try
        {
            var objectId = message.getInteger(AIOpsObject.OBJECT_ID);

            addEventSource(message.getString(EVENT_SOURCE));

            var startTime = System.currentTimeMillis();

            for (var resourceMetric : MetricsData.parseFrom(message.getBinary(EVENT)).getResourceMetricsList())
            {
                try
                {
                    var resourceAttributes = TraceConstants.parseAttribute(resourceMetric.getResource().getAttributesList(), null);

                    var service = resourceAttributes.getString(TraceConstants.SERVICE_NAME, TraceConstants.UNKNOWN_SERVICE);

                    service = "30Spans";

                    var serviceType = TraceServiceConfigStore.getStore().flatItems(TraceConstants.SERVICE_NAME, service, TraceConstants.SERVICE_TYPE);

                    message.put(TraceConstants.SERVICE_NAME,service);

                    var result = new JsonObject();

                    switch (TraceConstants.AgentType.valueOf(serviceType.getString(0)))
                    {

                        case TraceConstants.AgentType.JAVA ->  plugins.get(1L).method().invoke(plugins.get(1L).instance(),message);

                    }

                    for (var pluginId : result.fieldNames())
                    {
                        var metrics = result.getJsonArray(pluginId);

                        for (var i = 0; i < metrics.size(); i++)
                        {
                            var metric = metrics.getJsonObject(i);

                            TraceConstants.write(metric, (String) metric.remove("instance.key"), message.getInteger(AIOpsObject.OBJECT_ID), CommonUtil.getInteger(pluginId), builder, mappers);

                            TraceConstants.send(new JsonObject().put(RESULT, new JsonObject().put((String) metric.remove("policy.key"), new JsonArray().add(metric.put(TraceConstants.SERVICE_INSTANCE_KEY, service)))), objectId, CommonUtil.getInteger(pluginId), TraceServiceConfigStore.getStore().getIdByService(service));

                        }

                    }

                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
                finally
                {
                    if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                    {
//                        vertx.eventBus().send("trace.metric.test", new JsonObject()
//                                        .put("scalarMetric",jvmScalarMetrics)
//                                        .put("memoryMetric",jvmMemoryMetrics )
//                                        .put("gcMetric",jvmGcMetrics)
//                                        .put("classMetric",jvmClassMetrics)
//                                .put(TIME_STAMP, DateTimeUtil.currentSeconds())
//                                .put(ID, message.getInteger(AIOpsObject.OBJECT_ID)));
                    }

                }
            }

            LOGGER.info(String.format("Metric processing completed in %d ms", System.currentTimeMillis() - startTime));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /**
     * Updates the configuration for all registered plugins based on the provided event source IP address.
     * <p>
     * This method performs the following:
     * <ul>
     *     <li>Iterates over each plugin in the {@code plugins} list.</li>
     *     <li>If the environment is {@code ENV_TEST}, uses a hardcoded IP ("172.16.8.135") to fetch the configuration item.</li>
     *     <li>Otherwise, uses the given {@code eventSource} IP to fetch the corresponding configuration item.</li>
     *     <li>Updates the plugin with the retrieved configuration item using {@link ObjectConfigStore}.</li>
     * </ul>
     * <p>
     * This allows plugins to be dynamically updated with environment-specific configuration based on the source of incoming events.
     *
     * @param eventSource the IP address of the event source, used to retrieve the relevant configuration item.
     */
    private void addEventSource(String eventSource)
    {
        for (var plugin : TraceConstants.JVM_PLUGINS)
        {
            ObjectConfigStore.getStore().updateItemPlugin(plugin, ObjectConfigStore.getStore().getItemByIP(eventSource));
        }
    }



    /**
     * Loads a trace parser plugin from its configuration.
     * <p>
     * This method loads and initializes a custom trace parser plugin based on its configuration.
     * It performs the following steps:
     * <ul>
     *   <li>Constructs the plugin class name from the plugin name</li>
     *   <li>Checks if the plugin class file exists</li>
     *   <li>If it exists, loads the class and creates an instance</li>
     * </ul>
     * <p>
     * The method uses reflection to instantiate the plugin class and find its parse method.
     * It stores the plugin instance and method in the plugins map for later use.
     *
     * @param event The trace parser plugin configuration
     */
    private void loadPlugin(JsonObject event)
    {
        try
        {
            var fileName = event.getString("trace.parser.plugin.name").replace("-", "").replace(" ", "");

            if (vertx.fileSystem().existsBlocking(CURRENT_DIR + PATH_SEPARATOR + PLUGIN_SCRIPT_DIR + PATH_SEPARATOR + TRACE_PLUGIN_PARSER_DIR + PATH_SEPARATOR + fileName + ".class"))
            {

                var pluginClass = Class.forName(TRACE_PLUGIN_PARSER_DIR + "." + fileName, true, LOG_PLUGIN_CLASS_LOADER);

                plugins.put(event.getLong(ID), new TraceMetricProcessor.Plugin(pluginClass.getConstructor().newInstance(), pluginClass.getDeclaredMethod(PARSE_METHOD, JsonObject.class)));
            }

        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    /**
     * Stops the event engine gracefully when the Verticle is undeployed.
     * <p>
     * This method is called automatically by the Vert.x framework during shutdown.
     *
     * @param promise the promise to be completed when shutdown is finished
     * @throws Exception if any error occurs during shutdown
     */
    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        eventEngine.stop(vertx, promise);
    }

    record Plugin(Object instance, Method method)
    {

    }

