package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.DataRetentionPolicy;
import com.mindarray.api.Metric;
import com.mindarray.api.Report;
import com.mindarray.api.Tag;
import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.db.DBConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.policy.PolicyEngineConstants;
import com.mindarray.slo.SLOConstants;
import com.mindarray.store.*;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.CompositeFuture;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.ArrayList;
import java.util.Set;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.db.DBConstants.FIELD_NAME;
import static com.mindarray.policy.PolicyEngineConstants.POLICY_TAGS;


public class Patch810 implements Patch
{


    private static final Logger LOGGER = new Logger(Patch810.class, MOTADATA_PATCH, "Patch 8.1.0");

    private static final String VERSION = "8.1.0";

    private static final String NEW_TYPE = "Docker";

    /**
     * Returns the version number of this patch.
     *
     * @return The version string "8.1.0"
     */
    @Override
    public String getVersion()
    {
        return VERSION;
    }

    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("executing 8.1.0 patch...");

            var futures = new ArrayList<Future<Void>>();

            futures.add(deleteDuplicateReports());

            futures.add(executeDockerPatch());

            // Add retention patch
            futures.add(executeRetentionPatch());

            // Add policy tags patch
            futures.add(executePolicyTagsPatch());

            // Add plugin patch
            futures.add(executeMetricGroupAttachPatch());

            futures.add(createFloatingColumns());

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    // Initialize TagCacheStore after policy tags patch
                    TagCacheStore.getStore().initStore().onComplete(asyncResult ->
                    {
                        if (asyncResult.succeeded())
                        {
                            LOGGER.info("successfully executed 8.1.0 patch");

                            promise.complete();
                        }
                        else
                        {
                            LOGGER.error(asyncResult.cause());

                            promise.fail(asyncResult.cause());
                        }
                    });
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    private Future<Void> createFloatingColumns()
    {
        var promise = Promise.<Void>promise();

        var context = new JsonObject().put(SLOConstants.SLO_BURN_RATE, EMPTY_VALUE)
                .put(SLOConstants.SLO_INSTANCE_BURN_RATE, EMPTY_VALUE)
                .put(SLOConstants.SLO_OBJECT_BURN_RATE, EMPTY_VALUE);

        try
        {
            var file = new File(CURRENT_DIR + PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + PATH_SEPARATOR + DatastoreConstants.FLOATING_COLUMNS);

            if (file.exists())
            {
                LOGGER.info("floating columns already exists hence not creating");

                promise.complete();
            }
            else
            {
                Bootstrap.vertx().fileSystem().writeFileBlocking(file.getPath(), Buffer.buffer(context.encodePrettily().getBytes()));

                LOGGER.info("floating columns created successfully");

                promise.complete();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    private Future<Void> executeDockerPatch()
    {
        var promise = Promise.<Void>promise();

        migrateMetrics()
                .onComplete(result-> {

                    if (result.succeeded())
                    {
                        attachDockerContainerNetworkPlugin().onComplete(asyncResult-> {

                            if (asyncResult.succeeded())
                            {
                                promise.complete();
                            }
                            else
                            {
                                promise.fail(asyncResult.cause());
                            }
                        });

                    }
                    else {
                        promise.fail(result.cause());
                    }
                });

        return promise.future();
    }

    private Future<Void> attachDockerContainerNetworkPlugin()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var metrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_PLUGIN, NMSConstants.MetricPlugin.DOCKER_CONTAINER_DISK.getName());

            var networkMetrics = new JsonArray();

            for (var i = 0; i < metrics.size(); i++)
            {
                var metric = metrics.getJsonObject(i);

                var newMetric = new JsonObject().put(Metric.METRIC_NAME, "Docker Container Network")
                        .put(Metric.METRIC_PLUGIN, NMSConstants.MetricPlugin.DOCKER_CONTAINER_NETWORK.getName())
                        .put(Metric.METRIC_CONTEXT, metric.getJsonObject(Metric.METRIC_CONTEXT).put("plugin.id", 371));

                metric.mergeIn(newMetric);

                metric.remove(ID);

                networkMetrics.add(metric);


            }


            Bootstrap.configDBService().saveAll(DBConstants.TBL_METRIC, networkMetrics, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
            {
                if (result.succeeded())
                {
                    var futures = new ArrayList<Future<Void>>();

                    for (var record : result.result()) {

                        var addItemPromise = Promise.<Void>promise();

                        futures.add(addItemPromise.future());

                        MetricConfigStore.getStore().addItem((Long) record).onComplete(response ->
                        {
                            if (response.succeeded())
                            {
                                addItemPromise.complete();

                                LOGGER.info(String.format("Metric %s added successfully to MetricConfigStore", record));
                            }
                            else
                            {
                                addItemPromise.fail(response.cause());

                                LOGGER.error(response.cause());
                            }
                        });

                    }
                    Future.join(futures).onComplete(asyncResult->
                    {
                        if (asyncResult.succeeded())
                        {
                            promise.complete();
                        }
                        else
                        {
                            promise.fail(asyncResult.cause());
                        }

                    });

                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });


        }
        catch (Exception e)
        {
            LOGGER.error(e);

            promise.fail(e);
        }

        return promise.future();

    }

    /**
     * Updates metric.type field in MetricConfigStore.
     */
    private Future<Void> migrateMetrics()
    {
        var promise = Promise.<Void>promise();

        LOGGER.info("migrating Metrics...");

        try
        {
            var metrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_PLUGIN, "docker");

            var containerMetrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_PLUGIN, "dockercontainer");

            var containerProcessMetrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_PLUGIN, "dockercontainerprocess");

            var containerDiskMetrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_PLUGIN, "dockercontainerdisk");

            metrics.addAll(containerMetrics).addAll(containerProcessMetrics).addAll(containerDiskMetrics);

            if (metrics.isEmpty())
            {
                LOGGER.info("no metrics found with type Docker Container");

                promise.complete();

                return promise.future();
            }

            LOGGER.info(String.format("found %d metrics to migrate", metrics.size()));

            var futures = new ArrayList<Future<Void>>();

            for (var i = 0; i < metrics.size(); i++)
            {

                futures.add(updateMetric(metrics.getJsonObject(i)));
            }


            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully migrated all metrics");

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

