                            .put(SLOConstants.SLOFrequency.WEEKLY.getName(), new JsonObject().put("raw", 30))
                            .put(SLOConstants.SLOFrequency.MONTHLY.getName(), new JsonObject().put("raw", 90))
                            .put(SLOConstants.SLOFrequency.QUARTERLY.getName(), new JsonObject().put("raw", 180)));

