    /**
     * Attaches "oraclequery" and "oraclerecoveryarea" metrics to Oracle Database objects
     * if not already present. Saves and updates the metrics asynchronously.
     *
     * @return a Future completing when all patches are applied
     */
    private Future<Void> executeMetricGroupAttachPatch() {

        var promise = Promise.<Void>promise();

        var futures = new ArrayList<Future>();

        var items = ObjectConfigStore.getStore().getItemsByType(NMSConstants.Type.ORACLE_DATABASE);

        for (var item : items) {

            var metrics = MetricConfigStore.getStore().getItemsByObject((Long) item);

            var doPatch = true;

            for (var metric : metrics)
            {
                if (metric.getString(Metric.METRIC_PLUGIN).equals("oraclequery") || metric.getString(Metric.METRIC_PLUGIN).equals("oraclerecoveryarea"))
                {
                    doPatch = false;
                }
            }

            if (doPatch)
            {
                var itemPromise = Promise.promise();

                futures.add(itemPromise.future());

                var oracleQueryMetric = metrics.getFirst().mergeIn(ObjectManagerCacheStore.getStore().getItemByMetricPlugin("oraclequery"));

                oracleQueryMetric.remove(ID);

                var oracleRecoveryAreaMetric = metrics.get(1).mergeIn(ObjectManagerCacheStore.getStore().getItemByMetricPlugin("oraclerecoveryarea"));

                oracleRecoveryAreaMetric.remove(ID);

                Bootstrap.configDBService().saveAll(DBConstants.TBL_METRIC, new JsonArray().add(oracleQueryMetric).add(oracleRecoveryAreaMetric), DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                {
                    if (result.succeeded()) {

                        for (var record : result.result())
                        {
                            MetricConfigStore.getStore().addItem((Long) record).onComplete(response ->
                            {
                                LOGGER.info("successfully attached plugin for monitor " + item);

                            });
                        }

                        itemPromise.complete();
                    }
                    else
                    {
                        LOGGER.error(result.cause());

                        itemPromise.fail(result.cause());

                    }
                });
            }
        }

        CompositeFuture.all(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                LOGGER.info("successfully attached plugin for all monitors");

                promise.complete();
            }

            else
            {
                LOGGER.error(result.cause());

                promise.fail("Failed to attach plugin for all monitors with reason : " + result.cause().getMessage());

            }
        });

        return promise.future();
    }

