        var dir = new File(path);

        var bookmark = new File(path + GlobalConstants.PATH_SEPARATOR + "bookmarks");

        var offsets = new HashMap<Long, Long>();

        var events = new HashMap<Long, Long>();

        try
        {
            if (bookmark.exists())
            {
                var value = Files.readString(bookmark.toPath(), StandardCharsets.UTF_8);

                if (CommonUtil.isNotNullOrEmpty(value))
                {
                    for (var entry : new JsonObject(value))
                    {
                        offsets.put(CommonUtil.getLong(entry.getKey()), CommonUtil.getLong(entry.getValue().toString().split("_")[0]));

                        events.put(CommonUtil.getLong(entry.getKey()), CommonUtil.getLong(entry.getValue().toString().split("_")[1]));
                    }
                }
            }

            var files = dir.listFiles();

            if (files != null)
            {
                for (var file : files)
                {
                    if (file.getName().endsWith(".dat"))
                    {
                        var timestamp = CommonUtil.getLong(file.getName().split("\\.")[0].trim());

                        var fileOutputStream = new FileOutputStream(file, true);

                        var fileInputStream = new FileInputStream(file);

                        var bufferedOutputStream = new BufferedOutputStream(fileOutputStream, bytes.length);

                        var offset = offsets.getOrDefault(timestamp, 0L);

                        fileInputStream.skip(offset);

                        eventFiles.put(timestamp, new EventFile(bufferedOutputStream, fileInputStream, fileOutputStream, new AtomicLong(offset), new AtomicLong(events.getOrDefault(timestamp, 0L))));
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return events.values().stream().reduce(0L, Long::sum); //return total pending events...
    }

    protected void put(JsonObject event) throws Exception
    {
        try
        {
            var timestamp = event.getLong(EventBusConstants.EVENT_TIMESTAMP, DateTimeUtil.currentSeconds());

            if (timestamp > 0)
            {
                calendar.setTimeInMillis(timestamp * 1000); //seconds to millis

                calendar.set(Calendar.MILLISECOND, 0);

                calendar.set(Calendar.SECOND, 0);

                timestamp = calendar.getTimeInMillis();

                var eventFile = eventFiles.get(timestamp);

                if (eventFile == null)
                {
                    var file = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp + ".dat");

                    var fileOutputStream = new FileOutputStream(file, true);

                    var fileInputStream = new FileInputStream(file);

                    var bufferedOutputStream = new BufferedOutputStream(fileOutputStream, bytes.length);

                    eventFile = new EventFile(bufferedOutputStream, fileInputStream, fileOutputStream, new AtomicLong(0L), new AtomicLong(0L));

                    eventFiles.put(timestamp, eventFile);

                }

                var bufferBytes = CodecUtil.compress(event.encode());

                if (bufferBytes.length + 4 > this.bytes.length)
                {
                    this.bytes = new byte[bufferBytes.length + 4]; //if buffer bytes is larger than existing bytes then we must need to expand for the future read purpose...
                }

                ByteUtil.writeInt(this.bytes,bufferBytes.length,0);

                eventFile.bufferedOutputStream.write(bytes, 0, 4);

                eventFile.bufferedOutputStream.write(bufferBytes, 0, bufferBytes.length);

                eventFile.bufferedOutputStream.flush();

                eventFile.events().incrementAndGet(); //increment total events by file
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void put(byte[] bufferBytes) throws Exception
    {
        try
        {
            var timestamp = ByteUtil.readLongValue(bufferBytes); //get timetick from first 8 bytes

            if (timestamp > 0)
            {
                calendar.setTimeInMillis(timestamp);

                calendar.set(Calendar.MILLISECOND, 0);

                calendar.set(Calendar.SECOND, 0);

                timestamp = calendar.getTimeInMillis();

                var eventFile = eventFiles.get(timestamp);

                if (eventFile == null)
                {
                    var file = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp + ".dat");

                    var fileOutputStream = new FileOutputStream(file, true);

                    var fileInputStream = new FileInputStream(file);

                    var bufferedOutputStream = new BufferedOutputStream(fileOutputStream, bufferBytes.length);

                    eventFile = new EventFile(bufferedOutputStream, fileInputStream, fileOutputStream, new AtomicLong(0L), new AtomicLong(0L));

                    eventFiles.put(timestamp, eventFile);

                }

                eventFile.bufferedOutputStream.write(bufferBytes, 8, bufferBytes.length - 8); //skip first 8 bytes of timetick...

                eventFile.bufferedOutputStream.flush();

                eventFile.events().incrementAndGet();  //increment total events by file

                if (bufferBytes.length + 4 > this.bytes.length)
                {
                    this.bytes = new byte[bufferBytes.length + 4];  //if buffer bytes is larger than existing bytes then we must need to expand for the future read purpose...
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private byte[] getNativeBytes()
    {
        byte[] bufferBytes = null;
        try
        {
            for (var iterator = eventFiles.entrySet().iterator(); iterator.hasNext(); )
            {
                var entry = iterator.next();

                try
                {
                    ByteUtil.writeLong(this.bytes,entry.getKey(),0); //set first 8 bytes with timetick

                    var length = entry.getValue().fileInputStream.read(bytes, 8, 4); //8 bytes for timetick

                    if (length != 4) //means invalid file ... delete it skip to next file.
                    {
                        entry.getValue().fileInputStream.close();

                        entry.getValue().bufferedOutputStream.close();

                        entry.getValue().fileOutputStream.close();

                        iterator.remove();

                    }
                    else
                    {
                        length = ByteUtil.readIntValue(8,this.bytes); //skip 8 bytes of timetick

                        if (length != entry.getValue().fileInputStream.read(bytes, 12, length)) //means invalid file ... delete it skip to next file.
                        {
                            entry.getValue().fileInputStream.close();

                            entry.getValue().bufferedOutputStream.close();

                            entry.getValue().fileOutputStream.close();

                            iterator.remove();
                        }
                        else
                        {
                            entry.getValue().offset.addAndGet(length + 4); //mark read position

                            bufferBytes = new byte[length + 4 + 8]; // payload + length + timetick bytes

                            System.arraycopy(bytes, 0, bufferBytes, 0, bufferBytes.length);

                            return bufferBytes;
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return bufferBytes;
    }

    protected byte[] get(boolean nativeBytes)
    {
        byte[] bufferBytes = null;

        try
        {
            if (nativeBytes)
            {
                return getNativeBytes();
            }

            for (var iterator = eventFiles.entrySet().iterator(); iterator.hasNext(); )
            {
                var entry = iterator.next();

                try
                {
                    var length = entry.getValue().fileInputStream.read(bytes, 0, 4);

                    if (length != 4) //means invalid file ... delete it skip to next file.
                    {
                        entry.getValue().fileInputStream.close();

                        entry.getValue().bufferedOutputStream.close();

                        entry.getValue().fileOutputStream.close();

                        Files.deleteIfExists(Paths.get(path + GlobalConstants.PATH_SEPARATOR + entry.getKey() + ".dat"));

                        iterator.remove();
                    }
                    else
                    {
                        length = ByteUtil.readIntValue(bytes);

                        if (length != entry.getValue().fileInputStream.read(bytes, 0, length)) //means invalid file ... delete it skip to next file.
                        {
                            entry.getValue().fileInputStream.close();

                            entry.getValue().bufferedOutputStream.close();

                            entry.getValue().fileOutputStream.close();

                            Files.deleteIfExists(Paths.get(path + GlobalConstants.PATH_SEPARATOR + entry.getKey() + ".dat"));

                            iterator.remove();
                        }
                        else
                        {
                            entry.getValue().offset.addAndGet(length + 4); //mark read position

                            bufferBytes = CodecUtil.toBytes(bytes, 0, length); //plain  uncompressed bytes...

                            return bufferBytes;
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return bufferBytes;

    }

    protected void saveBookmarks()
    {
        try
        {
            var bookmarks = new JsonObject();

            eventFiles.forEach((key, value) -> bookmarks.put(CommonUtil.getString(key), value.offset.get() + "_" + value.events.get())); // offset+event queue size

            Bootstrap.vertx().fileSystem().writeFileBlocking(path + GlobalConstants.PATH_SEPARATOR + "bookmarks", bookmarks.toBuffer());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void close()
    {
        try
        {
            for (var iterator = eventFiles.entrySet().iterator(); iterator.hasNext(); )
            {
                var entry = iterator.next();

                entry.getValue().fileInputStream.close();

                entry.getValue().bufferedOutputStream.close();

                entry.getValue().fileOutputStream.close();

                Files.deleteIfExists(Paths.get(path + GlobalConstants.PATH_SEPARATOR + entry.getKey() + ".dat"));

                iterator.remove();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private
    record EventFile(BufferedOutputStream bufferedOutputStream, FileInputStream fileInputStream,
                     FileOutputStream fileOutputStream, AtomicLong offset, AtomicLong events)
    {

    }

}

