package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.datagram.DatagramSocket;
import io.vertx.core.datagram.DatagramSocketOptions;
import io.vertx.core.json.JsonObject;

import static com.mindarray.GlobalConstants.HOST;
import static com.mindarray.GlobalConstants.PORT;

public class UDPServer implements TransportServer
{
    private final JsonObject config;

    private final String eventType;

    private  DatagramSocket server;

    private static final Logger LOGGER = new Logger(UDPServer.class, GlobalConstants.MOTADATA_EVENT_BUS, "UDP Server");

    private final int port;

    private final String host;

    UDPServer(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EventBusConstants.EVENT_TYPE);

        port = config.getInteger(PORT);

        host = config.getString(HOST);
    }

    @Override
    public Future<Void> bind()
    {
        var promise = Promise.<Void>promise();

        server = Bootstrap.vertx().createDatagramSocket(new DatagramSocketOptions().setReusePort(true).setReuseAddress(true));

        server.listen(port, host, handler ->
        {
            if (handler.succeeded())
            {
                LOGGER.info(String.format("Server is successfully connected with port %s", port));

                promise.complete();
            }
            else
            {
                promise.fail(handler.cause());
            }
        });

        return promise.future();
    }

    @Override
    public void send(String topic, byte[] data)
    {
        server.send(Buffer.buffer(data),port,host);
    }

    @Override
    public Future<Void> receive()
    {
        server.handler(packet ->
        {
            var buffer = packet.data();

            if (buffer.length() > 0)
            {
                Bootstrap.vertx().eventBus().send(eventType, buffer.getBytes());
            }
        });

        return Future.succeededFuture();
    }

    @Override
    public Future<Void> close()
    {
        return server.close();
    }
}

