    {
        // by default, master sender will bind on 9444,9445 port.
        // by default, master receiver will bind on 9449,9450 port.


        // for collector,slave,replica remote receiver will connect on 9444,9445
        // for collector,slave,replica remote forwarder will connect on 9449,9450

        if (Bootstrap.bootstrapType() == BootstrapType.FLOW_COLLECTOR ||
                Bootstrap.bootstrapType() == BootstrapType.EVENT_PROCESSOR ||
                Bootstrap.bootstrapType() == BootstrapType.COLLECTOR ||
                Bootstrap.bootstrapType() == BootstrapType.EVENT_COLLECTOR || Bootstrap.bootstrapType() == BootstrapType.MANAGER
                || (Bootstrap.bootstrapType() == BootstrapType.APP && getInstallationMode().equalsIgnoreCase(InstallationMode.SECONDARY.name()) || getInstallationMode().equalsIgnoreCase(InstallationMode.FAILOVER.name())))
        {
            return switch (EventBusConstants.TransportProtocol.valueOfName(protocol))
            {
                case ZMQ -> configs.getInteger(EVENT_PUBLISHER_PORT, 9449);

                case TCP -> configs.getInteger(EVENT_PUBLISHER_PORT, 9483);

                case UDP -> configs.getInteger(EVENT_PUBLISHER_PORT, 9493);

                case HTTP -> configs.getInteger(EVENT_PUBLISHER_PORT, 9503);
            };
        }
        else if (Bootstrap.bootstrapType() == BootstrapType.APP)
        {
            return switch (EventBusConstants.TransportProtocol.valueOfName(protocol))
            {
                case ZMQ -> configs.getInteger(EVENT_PUBLISHER_PORT, 9444);

                case TCP -> configs.getInteger(EVENT_PUBLISHER_PORT, 9478);

                case UDP -> configs.getInteger(EVENT_PUBLISHER_PORT, 9488);

                case HTTP -> configs.getInteger(EVENT_PUBLISHER_PORT, 9498);
            };
        }

        return 9444;
    }

