     * </ul>
     *
     * @param protocol the transport protocol name
     * @return reconnect interval in milliseconds
     */
    public static int getEventRemoteReconnectIntervalSeconds(String protocol)
    {
        if (configs.containsKey("event.remote.socket.reconnect.interval.seconds"))
