    /**
     * Returns the configured TCP buffer size in bytes.
     * <p>
     * If {@code tcp.buffer.size.bytes} is defined in the configuration,
     * it is used (in KB, multiplied by 1024).
     * Otherwise, the size is determined by the deployment type:
     * <ul>
     *   <li>Type 0 → 512 KB</li>
     *   <li>Type 1 → 1024 KB</li>
     *   <li>Type 2 → 1536 KB</li>
     *   <li>Type 3 → 2048 KB</li>
     *   <li>Default → uses {@code tcp.buffer.size.bytes} (KB)</li>
     * </ul>
     *
     * @return TCP buffer size in bytes
     */
    public static int getTCPBufferSizeBytes()
    {
        if (configs.containsKey("tcp.buffer.size.bytes"))
        {
            return configs.getInteger("tcp.buffer.size.bytes",512) * 1024;
        }
        else
        {
            return switch (getDeploymentType())
            {
                case 0 -> 512 * 1024;

                case 1 -> 2 * 512 * 1024;

                case 2 -> 3 * 512 * 1024;

                case 3 -> 4 * 512 * 1024;

                default ->  configs.getInteger("tcp.buffer.size.bytes",512) * 1024;
            };
        }
    }

