     * <ul>
     *   <li>Type 0 → 512 KB</li>
     *   <li>Type 1 → 1024 KB</li>
     *   <li>Type 2 → 1536 KB</li>
     *   <li>Type 3 → 2048 KB</li>
     *   <li>Default → uses {@code tcp.buffer.size.bytes} (KB)</li>
     * </ul>
     *
     * @return HTTP buffer size in bytes
     */
    public static int getHTTPBufferSizeBytes()
    {
        if (configs.containsKey("http.buffer.size.bytes"))
        {
            return configs.getInteger("http.buffer.size.bytes",2048) * 1024;
        }
        else
        {
            return switch (getDeploymentType())
            {
                case 0 -> 2 * 512 * 1024;

                case 1 -> 4 * 512 * 1024;

                case 2 -> 6 * 512 * 1024;

                case 3 -> 8 * 512 * 1024;

                default ->  configs.getInteger("http.buffer.size.bytes",2048) * 1024;
            };
        }
    }

