package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.DateTimeUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.concurrent.atomic.AtomicLong;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.InfoMessageConstants.ENTITY_UPDATED;
import static com.mindarray.api.APIConstants.VIEW;
import static com.mindarray.datastore.DatastoreConstants.DATASTORE_CATEGORY;
import static com.mindarray.datastore.DatastoreConstants.DATASTORE_UUID;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.util.AuditUtil.*;

/**
 * <p>
 * The primary responsibilities of the class include:
 * <ul>
 *     <li>Listening for and responding to events regarding the state of the datastore (e.g., up or down).</li>
 *     <li>Loading and closing event files based on the status and duration of the datastore being up or down.</li>
 *     <li>Managing event retention and initiating retention operations based on retention policies.</li>
 *     <li>Sending events to the datastore (including in High Availability (HA) setups) for persistent storage.</li>
 * </ul>
 *
 * The class uses Vert.x's event bus to send and receive messages regarding the state and actions of the datastore.
 * It utilizes the {@link DatastoreEngine} for event storage and processing and interacts with other components such
 * as event processors, retention triggers, and HA sync mechanisms.
 *
 * Key features:
 * <ul>
 *     <li>Responds to event "pings" that indicate whether the datastore is up or down, and adjusts the state of the event engine accordingly.</li>
 *     <li>Tracks the duration that the datastore has been down and takes appropriate actions after a certain threshold (e.g., 30 minutes), such as closing event files from memory.</li>
 *     <li>Handles retention operations by listening for retention triggers and executing retention logic based on configuration.</li>
 *     <li>Supports High Availability (HA) environments, sending events either to a local datastore or to a primary datastore, depending on the mode.</li>
 *     <li>Supports development mode for testing purposes by sending trace events to a separate test destination.</li>
 * </ul>
 *
 */
public class TraceDatastore extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(TraceDatastore.class, MOTADATA_DATASTORE, "Trace Datastore");
    private static final boolean STANDALONE_OR_PRIMARY = Bootstrap.getInstallationMode().equalsIgnoreCase(InstallationMode.STANDALONE.name()) || Bootstrap.getInstallationMode().equalsIgnoreCase(InstallationMode.PRIMARY.name());
    private final AtomicLong duration = new AtomicLong();
    private DatastoreEngine eventEngine;
    private boolean closed = false;
    private String uuid;
    private static final String PORT = CommonUtil.getString(MotadataConfigUtil.getTraceDatastoreWriterPort());

    /**
     * <p>
     * - Listens for the datastore "ping" events and updates status based on the event data.
     * - If the datastore was down for over 30 minutes, it loads files and marks the datastore as active.
     * - If the datastore is down for more than a configured time, it closes event files in memory.
     * - Initializes the DatastoreEngine to handle event data and process events.
     * - Listens for retention trigger events to run data retention logic.
     * - Sets up consumers for "active" and "inactive" states of the datastore.
     *
     * @param promise A Promise for the start-up process.
     * @throws Exception If an error occurs during the start-up process.
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            vertx.eventBus().<JsonObject>localConsumer(EVENT_DATASTORE_PING, message ->
            {
                var event = message.body();

                try
                {
                    if (uuid.equalsIgnoreCase(event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)))
                    {
                        if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace(String.format("updating status for  %s : %s , event type : %s", event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID), event.getString(STATUS), config().getString(EVENT_TYPE)));
                        }

                        if (event.getString(STATUS).equalsIgnoreCase(STATUS_UP))
                        {
                            if (event.getString(PORT,EMPTY_VALUE).equalsIgnoreCase(STATUS_UP))
                            {
                                // if database gets up after being down more than 30 minutes then load all files
                                if (closed)
                                {
                                    vertx.eventBus().send(config().getString(EventBusConstants.EVENT_TYPE) + ".load", uuid);

                                    duration.set(0);

                                    closed = false;

                                    LOGGER.info(String.format("loading files for : %s ", config().getString(EVENT_TYPE)));
                                }

                                vertx.eventBus().send(config().getString(EventBusConstants.EVENT_TYPE) + ".active", uuid);

                                LOGGER.debug(String.format("active : type  %s ", config().getString(EVENT_TYPE)));
                            }
                            else
                            {
                                LOGGER.warn(String.format("port %s status is %s  from datastore to APP : event type : %s  ",PORT,event.getString(PORT,EMPTY_VALUE),config().getString(EVENT_TYPE)));
                            }
                        }
                        else
                        {
                            duration.getAndIncrement();
                        }

                        // 180 * 10 = 1800 sec(30 min) . if datastore is down for more than 30 minutes
                        // then close all event files object from in memory

                        if (duration.get() > MotadataConfigUtil.getDatastoreFileCloseTimerSeconds())
                        {
                            vertx.eventBus().send(config().getString(EventBusConstants.EVENT_TYPE) + ".close", uuid);

                            closed = true;

                            vertx.eventBus().send(EVENT_AUDIT_WRITE,new JsonObject().put(AUDIT_MODULE,SYSTEM_HEATH).put(AUDIT_OPERATION,VIEW)
                                    .put(AUDIT_MESSAGE,String.format(String.format(ENTITY_UPDATED, SYSTEM_HEATH) + GlobalConstants.NEW_LINE +
                                            new JsonObject().put("new.prop.value",new JsonObject()
                                                    .mergeIn(RemoteEventProcessorConfigStore.getStore().flatItemsByValue(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, uuid, RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.DATASTORE.name()).getJsonObject(0))
                                                    .put(DATASTORE_UUID,uuid).put(DURATION,duration.get())
                                                    .put(EVENT_TYPE,config().getString(EventBusConstants.EVENT_TYPE))
                                                    .put("datastore.file.close.timer.seconds",MotadataConfigUtil.getDatastoreFileCloseTimerSeconds())
                                                    .put(MANAGER_UUID,Bootstrap.getRegistrationId()).put(INSTALLATION_MODE,Bootstrap.getInstallationMode())
                                                    .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                                    .put(TIME,DateTimeUtil.getScheduledTimestamp(DateTimeUtil.currentMilliSeconds()))
                                                    .put(MESSAGE, "Datastore file has been closed. Reason : Datastore is down for long time")).encodePrettily())));

                            duration.set(0);

                            LOGGER.info(String.format("closing files for : %s ", config().getString(EVENT_TYPE)));
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });

            vertx.eventBus().<Void>localConsumer(EVENT_DATASTORE_RETENTION_TRIGGER, message ->
                    DatastoreConstants.runRetention(config().getString(EventBusConstants.EVENT_TYPE), DateTimeUtil.currentMilliSeconds() - MotadataConfigUtil.getTraceDatastoreRetentionDays() * 86400000L, LOGGER));

            eventEngine = new DatastoreEngine()
                    .setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                    .setPersistEventOffset(true)
                    .setEventQueueSize(MotadataConfigUtil.getTraceDatastoreEngineQueueSize())
                    .setStatus(false)
                    .setLogger(LOGGER)
                    .setDynamicQueueSize(true)
                    .setEventHandler(this::send)
                    .start(vertx, promise);

            uuid = config().getString(EventBusConstants.EVENT_TYPE).split(DOT_SEPARATOR_ESCAPE)[3];

            vertx.eventBus().<Void>localConsumer(config().getString(EventBusConstants.EVENT_TYPE) + ".inactive", message ->
            {
                LOGGER.debug(String.format("inactivate : type  %s ", config().getString(EVENT_TYPE)));

                eventEngine.setStatus(false);
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }
    }

    /**
     * Sends the given event data to the datastore based on the current mode (Standalone/Primary or Secondary/HA).
     * <p>
     * - If the system is in Standalone or Primary mode, it sends the event to the datastore write endpoint.
     * - If the system is in Secondary/HA mode, it sends the event to the remote event bus to sync with the primary datastore.
     * - In both cases, the event is enriched with relevant metadata such as UUID and event topic.
     * - In development mode, it sends the event to a test event bus for debugging purposes.
     *
     * @param event The event data to be sent to the datastore.
     */
    private void send(JsonObject event)
    {
        if (STANDALONE_OR_PRIMARY)
        {
            vertx.eventBus().send(EVENT_PUBLICATION_DATASTORE_WRITE + DOT_SEPARATOR + DatastoreConstants.DatastoreCategory.TRACE.getName(), event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, uuid).put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC));

            if (CommonUtil.traceEnabled())
            {
                LOGGER.trace(String.format("event sent to datastore %s , timestamp : %s", uuid, event.getLong(EVENT_TIMESTAMP)));
            }
        }
        else
        {
            vertx.eventBus().send(EVENT_REMOTE, event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, uuid).put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, Bootstrap.getInstallationMode()).put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName()).put(EVENT_TYPE, EVENT_HA_DATASTORE_SECONDARY_SYNC));

            if (CommonUtil.traceEnabled())
            {
                LOGGER.trace(String.format("datastore event sent to primary app with timestamp : %s ", event.getLong(EVENT_TIMESTAMP)));
            }
        }

        if (MotadataConfigUtil.devMode())
        {
            vertx.eventBus().send("test.datastore.trace", event);
        }
    }

    @Override
    public void stop(Promise<Void> promise)
    {
        eventEngine.stop(vertx, promise);
    }
}
