package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.util.CodecUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import com.mindarray.visualization.VisualizationConstants;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import org.apache.commons.io.FileUtils;

import java.io.File;
import java.nio.charset.StandardCharsets;

import static com.mindarray.GlobalConstants.*;

public class Patch801 implements Patch
{

    private static final Logger LOGGER = new Logger(Patch801.class, MOTADATA_PATCH, "Patch 8.0.1");

    public boolean applyPatch(boolean freshInstallation, String version)
    {
        return !freshInstallation && version.equalsIgnoreCase("8.0.0");
    }

    @Override
    public void doPatch()
    {

        var path = CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + "event-columns";

        var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + "event-columns");

        var columns = new JsonObject();

        try
        {
            if (file.exists())
            {
                var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    columns = (new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))));

                    for (var key : columns.getMap().keySet())
                    {
                        var ids = columns.getJsonObject(key).getJsonArray(DatastoreConstants.MAPPER_PLUGIN_IDS);

                        for (var id : ids)
                        {
                            if (CommonUtil.getLong(id) == DatastoreConstants.PluginId.GENERIC_LOG_EVENT.getName())
                            {
                                LOGGER.info("assigning event.history to mapper.event.category for " + key);

                                columns.getJsonObject(key).put(DatastoreConstants.MAPPER_EVENT_CATEGORY, VisualizationConstants.VisualizationDataSource.EVENT_HISTORY.getName());
                            }
                        }
                    }

                    Bootstrap.vertx().fileSystem().writeFileBlocking(path, Buffer.buffer(CodecUtil.compress(columns.encode().getBytes())));
                }
            }

            // update required of VERSION file

            var content = FileUtils.readFileToString(new File(CURRENT_DIR + PATH_SEPARATOR + VERSION_FILE), StandardCharsets.UTF_8);

            content = "8.0.1" + content.substring(5);

            FileUtils.writeStringToFile(new File(CURRENT_DIR + PATH_SEPARATOR + VERSION_FILE), content);

            MotadataConfigUtil.loadArtifactVersions();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

