package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.agent.AgentEventProcessor;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.Logger;
import io.vertx.core.json.JsonObject;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.db.DBConstants.COLLECTION_REMOTE_EVENT_PROCESSOR;
import static com.mindarray.db.DBConstants.FIELD_NAME;

public class _8_0_1_RemoteEventProcessor implements Patch
{
    private static final Logger LOGGER = new Logger(AgentEventProcessor.class, "patch", "Remote Poller Patch");

    @Override
    public void doPatch()
    {
        var items = RemoteEventProcessorConfigStore.getStore().getItems();

        System.out.println(items);

        for (var i = 0; i < items.size(); i++)
        {
            var item = items.getJsonObject(i);

            if (!item.containsKey(RemoteEventProcessor.REMOTE_EVENT_TYPE))
            {
                if (item.containsKey(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE) && item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE).equalsIgnoreCase(BootstrapType.DEFAULT.name()))
                {
                    item.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.MASTER.name());
                }
                Bootstrap.configDBService.update(COLLECTION_REMOTE_EVENT_PROCESSOR,
                        new JsonObject().put(FIELD_NAME, ID)
                                .put(VALUE, item.getLong(ID)),
                        item.put(RemoteEventProcessor.REMOTE_EVENT_TYPE, "REMOTE POLLER"),
                        SYSTEM_USER, SYSTEM_REMOTE_ADDRESS, true, result ->
                        {
                            if (result.succeeded())
                            {
                                RemoteEventProcessorConfigStore.getStore().updateItem(item.getLong(ID));

                                LOGGER.info("updated item : " + RemoteEventProcessorConfigStore.getStore().getItem(item.getLong(ID)));
                            }
                        });
            }
        }
    }
}

