@ExtendWith(VertxExtension.class)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
@Timeout(70 * 1000)
@EnabledIfSystemProperty(named = "test.mode", matches = "FLOW_COLLECTOR")
public class TestFlowCollector
{
    private static MessageConsumer<JsonObject> eventDBWriteTestConsumer;
    private static ZMQ.Socket producer;
    private static final Logger LOGGER = new Logger(TestFlowCollector.class, "Test Flow Collector", "Test Flow Processor");


    @BeforeAll
    static void beforeAll(VertxTestContext testContext)
    {
        try
        {
            testContext.awaitCompletion(10, TimeUnit.SECONDS);

            var deploymentId = Bootstrap.getDeployedVerticles().get(RemoteEventSender.class.getSimpleName() + " 9450");

            Bootstrap.vertx().undeploy(deploymentId, result ->
            {
                if (result.succeeded())
                {
                    var deploymentID = Bootstrap.getDeployedVerticles().get(RemoteEventSender.class.getSimpleName() + " 9449");

                    Bootstrap.vertx().undeploy(deploymentID, asyncResult ->
                    {
                        if (asyncResult.succeeded())
                        {
                            LOGGER.info("Remote Event Sender undeployed successfully.");

                            Bootstrap.vertx().eventBus().publish(EVENT_CONFIG_INIT, new JsonObject().put(STATUS, STATUS_SUCCEED));

                            testContext.completeNow();
                        }
                        else
                        {
                            LOGGER.warn("Failed  to undeployed RemoteEventSender verticle.", asyncResult.cause());
                        }
                    });
                }
            });

            producer = Bootstrap.zcontext().socket(SocketType.PUSH);

            producer.connect("tcp://*:" + CommonUtil.getEventReceiverPort(MotadataConfigUtil.getEventAppReceiverProtocols().get(0)));

        }
        catch (Exception exception)
        {
            testContext.failNow(exception);
        }
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    @Timeout(5000)
    void testFlowCollector(VertxTestContext testContext) throws InterruptedException
    {

        testContext.awaitCompletion(5, TimeUnit.SECONDS);

        eventDBWriteTestConsumer = TestUtil.vertx().eventBus().localConsumer(EventBusConstants.EVENT_REMOTE, message -> //this event will be
        {
            try
            {
                var event = message.body();

                LOGGER.info("Event received in test case: " + event.toString());

                if (EVENT_FLOW.equalsIgnoreCase(event.getString(EVENT_TYPE)))
                {
                    Assertions.assertNotNull(event);

                    Assertions.assertEquals(EVENT_FLOW, event.getString(EVENT_TYPE));

                    Assertions.assertEquals(467, event.getInteger(EVENT_VOLUME_BYTES));

                    Assertions.assertEquals(DatastoreConstants.PluginId.FLOW_EVENT.getName(), event.getInteger(PLUGIN_ID));

                    eventDBWriteTestConsumer.unregister();

                    testContext.completeNow();
                }
            }
            catch (Exception exception)
            {
                LOGGER.warn("Failed  to check Assertions.", exception);

                testContext.failNow(exception);
            }
        });

        producer.send(Buffer.buffer().appendShortLE(CommonUtil.getShort(EventBusConstants.FLOW_TOPIC.length())).appendString(EventBusConstants.FLOW_TOPIC).appendBytes("{\"tag\": 1, \"class\": \"unknown\", \"peer_ip_src\": \"8.8.8.8\", \"peer_ip_dst\": \"\", \"iface_in\": 0, \"iface_out\": 0, \"ip_src\": \"1.1.1.1\", \"ip_dst\": \"8.8.4.4\", \"port_src\": 40, \"port_dst\": 80, \"tcp_flags\": \"0\", \"ip_proto\": \"6\", \"tos\": 0, \"sampling_rate\": 10, \"timestamp_start\": \"2022-09-07 14:56:11.000000\", \"timestamp_end\": \"2022-09-07 14:56:11.000000\", \"export_proto_seqno\": 1, \"export_proto_version\": 5, \"flows\": 1, \"packets\": 902, \"bytes\": 393, \"flow_type\": \"NetFlow\"}".getBytes()).getBytes());

        Assertions.assertTrue(testContext.awaitCompletion(20, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(2)
    public void testRemoteEventConfigChange(VertxTestContext testContext) throws InterruptedException
    {
        var id = 49983344835L;

        var context = new JsonObject("{\"event.type\":\"change.notification\",\"event.topic\":\"remote.event.processor\",\"table\":\"tbl_config_flow_sampling_rate\",\"change.notification.type\":\"CONFIG_CHANGE\",\"request\":\"create\",\"id\":49983344835,\"result\":{\"event.source\":\"172.16.10.1\",\"interface.index\":31,\"interface.sampling.rate\":1,\"event.id\":49983344889,\"_type\":\"1\",\"interface.custom.sampling.rate\":10}}").put(GlobalConstants.ID, id);

        TestUtil.vertx().eventBus().send(EventBusConstants.EVENT_CHANGE_NOTIFICATION, context);

        TestUtil.vertx().setTimer(5000, handler ->
        {
            var item = FlowSamplingRateConfigStore.getStore().getItem(id);

            Assertions.assertNotNull(item);

            testContext.completeNow();
        });

        Assertions.assertTrue(testContext.awaitCompletion(20, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");

    }
}

