    public JsonArray getItemsBySeverity(String severity)
    {
        var items = new JsonArray();

        for (var entry : objects.entrySet())
        {
            if (severity.equalsIgnoreCase(objects.get(entry.getKey())))
            {
                var object = ObjectConfigStore.getStore().getItem(entry.getKey());

                if (object != null)
                {
                    items.add(new JsonObject().put(ID, entry.getKey()).put(OBJECT_NAME, object.getString(AIOpsObject.OBJECT_NAME)).put(OBJECT_IP, object.getString(OBJECT_IP, object.getString(OBJECT_TARGET))).put(SEVERITY, severity).put(OBJECT_ID, object.getInteger(OBJECT_ID)));
                }
            }
        }

        return items;
    }

    /**
     * Notifies listeners about severity changes for the given ID.
     * This method collects all policy keys associated with the object and triggers the notification logic.
     *
     * @param id the object/entity ID for which to notify severity changes
     */
    public void notify(long id)
    {
        notify(id, new HashSet<>(Arrays.asList(policyKeysByObject.get(id).split(COMMA_SEPARATOR))));
    }

    private void loadSeverities()
    {
        try
        {
            try
            {
                var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + PolicyEngineConstants.METRIC_POLICY_SEVERITIES);

                if (file.exists())
                {
                    var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

                    if (buffer != null && buffer.getBytes().length > 0)
                    {
                        var context = new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).getMap();

                        ((Map<String, Object>) (context.get("objects"))).forEach((key, value) -> objects.put(CommonUtil.getLong(key), CommonUtil.getString(value)));

                        ((Map<String, Object>) (context.get("apps"))).forEach((key, value) -> apps.put(key, CommonUtil.getString(value)));

                        ((Map<String, Object>) (context.get("instances"))).forEach((key, value) -> instances.put(key, CommonUtil.getString(value)));

                        LOGGER.info("loaded object cache severities");
                    }
                }
                else
                {
                    Bootstrap.vertx().fileSystem().createFileBlocking(file.getPath());
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    public boolean dirty()
    {
        return dirty.get();
    }

    public void setDirty(boolean value)
    {
        dirty.set(value);
    }

    public void dump(String path)
    {
        if ((!objects.isEmpty() || !apps.isEmpty() || !instances.isEmpty()) && updated.get())
        {
            Bootstrap.vertx().<Void>executeBlocking(promise ->
            {
                try
                {
                    Bootstrap.vertx().fileSystem().writeFileBlocking(path,
                            Buffer.buffer(CodecUtil.compress(new JsonObject().put("objects", new HashMap<>(objects)).put("instances", new HashMap<>(instances)).put("apps", new HashMap<>(apps)).encode().getBytes())));
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }

                promise.complete();
            });

            updated.set(false);

            dirty.set(true);
        }
    }
}

