        try (var producer = Bootstrap.zcontext().socket(SocketType.PUSH))
        {
            producer.connect("tcp://*:" + CommonUtil.getEventReceiverPort(MotadataConfigUtil.getEventAppReceiverProtocols().get(0)));

            for (var index = 0; index < TOTAL_AGENTS; index++)
            {
                var agent = new JsonObject().put("object.ip", String.format("10.20.41.%s", (1 + index)))
                        .put("agent.version", "8.1.0")
                        .put("agent.os.name", "linux")
                        .put("objects", new JsonArray().add(String.format("10.20.41.%s", (1 + index))))
                        .put("agent.id", "AGENT-YASH" + index)
                        .put("event.type", "agent.registration")
                        .put("object.host", "agent-test-" + (1+ index))
                        .put("agent.configs", new JsonObject().put("agent", new JsonObject()
                                .put("agent.id", "AGENT-YASH" + index)
                                .put("agent.deactivation.status", "no")
                                .put("metric.agent.status", "no")
                                .put("agent.state", "ENABLE")));

                producer.send(Buffer.buffer().appendShortLE(CommonUtil.getShort(EventBusConstants.AGENT_TOPIC.length())).appendString(EventBusConstants.AGENT_TOPIC).appendBytes(cipherUtil.encrypt(CodecUtil.compress(agent.encode()))).getBytes());
            }

            testContext.completeNow();
