package com.mindarray;

import com.mindarray.db.*;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.eventbus.RemoteEventChangeNotificationHandler;
import com.mindarray.eventbus.RemoteEventForwarder;
import com.mindarray.eventbus.RemoteEventSubscriber;
import com.mindarray.ha.ConfigManager;
import com.mindarray.util.*;
import io.vertx.core.CompositeFuture;
import io.vertx.core.Future;
import io.vertx.core.Promise;

import java.util.ArrayList;

import static com.mindarray.Bootstrap.*;
import static com.mindarray.GlobalConstants.INSTALLATION_DATE;

public class BootstrapFailover
{
    private static final Logger LOGGER = new Logger(BootstrapFailover.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Replica");

    public void start()
    {
        try
        {
            // TODO :- as of now temporarily making below condition true.
            if (true || PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
            {
                DBConstants.loadDBConfigs();

                Bootstrap.logSystemConfig();

                ProcessUtil.setProcessors();

                EventBusConstants.setRemoteEventProcessorRegistrationId();

                startEngine(new ConfigDBServiceProvider(), ConfigDBServiceProvider.class.getSimpleName(), null)
                        .compose(future -> startEngine(new RemoteEventForwarder(MotadataConfigUtil.getMotadataObserverEventSubscriberPort(),MotadataConfigUtil.getRemoteEventObserverSubscriber()), RemoteEventForwarder.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventSubscriberPort(), null))
                        .compose(future -> startEngine(new RemoteEventSubscriber(MotadataConfigUtil.getMotadataObserverEventPublisherPort(),MotadataConfigUtil.getRemoteEventObserverPublisher()), RemoteEventSubscriber.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventPublisherPort(), null))
                        .onComplete(resultHandler ->
                        {
                            if (resultHandler.succeeded())
                            {
                                ConfigDBInitializer.init().onComplete(configHandler ->
                                {
                                    if (configHandler.succeeded())
                                    {
                                        var futures = new ArrayList<Future>();

                                        var forwarderPort = CommonUtil.getEventPublisherPort();

                                        for (var index = 0; index < MotadataConfigUtil.getEventPublishers(); index++)
                                        {
                                            var promise = Promise.promise();

                                            futures.add(promise.future());

                                            Bootstrap.startEngine(new RemoteEventForwarder(forwarderPort + index), RemoteEventForwarder.class.getSimpleName() + " " + (forwarderPort + index), null).onComplete(handler ->
                                            {
                                                if (handler.succeeded())
                                                {
                                                    promise.complete();
                                                }
                                                else
                                                {
                                                    promise.fail(handler.cause());
                                                }
                                            });
                                        }

                                        CompositeFuture.join(futures).onComplete(asyncResult ->
                                        {
                                            if (asyncResult.succeeded())
                                            {
                                                var asyncResults = new ArrayList<Future>();

                                                var subscriberPort = CommonUtil.getEventSubscriberPort();

                                                for (var index = 0; index < MotadataConfigUtil.getEventSubscribers(); index++)
                                                {
                                                    var promise = Promise.promise();

                                                    asyncResults.add(promise.future());

                                                    Bootstrap.startEngine(new RemoteEventSubscriber(subscriberPort + index), RemoteEventSubscriber.class.getSimpleName() + " " + (subscriberPort + index), null).onComplete(voidAsyncResult ->
                                                    {
                                                        if (voidAsyncResult.succeeded())
                                                        {
                                                            promise.complete();
                                                        }
                                                        else
                                                        {
                                                            promise.fail(voidAsyncResult.cause());
                                                        }
                                                    });
                                                }

                                                CompositeFuture.join(asyncResults).onComplete(handler ->
                                                {
                                                    startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null)
                                                            .compose(future -> startEngine(new ConfigManager(), ConfigManager.class.getSimpleName(), null))
                                                            .onComplete(result ->
                                                            {
                                                                try
                                                                {
                                                                    if (result.succeeded())
                                                                    {
                                                                        Bootstrap.configDBService().getOne(DBConstants.COLLECTION_SYSTEM,
                                                                                response ->
                                                                                {
                                                                                    if (response.succeeded())
                                                                                    {
                                                                                        LicenseUtil.init(!response.result().containsKey(INSTALLATION_DATE)).onComplete(asyncResponse ->
                                                                                        {
                                                                                            if (asyncResponse.succeeded())
                                                                                            {
                                                                                                try
                                                                                                {
                                                                                                    LOGGER.info("license verified successfully...");

                                                                                                    LicenseUtil.load(asyncResponse.result());

                                                                                                    EventBusConstants.register(new CipherUtil(), Bootstrap.bootstrapType(), MotadataConfigUtil.getInstallationMode());

                                                                                                    LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, GlobalConstants.InstallationMode.FAILOVER));
                                                                                                }
                                                                                                catch (Exception exception)
                                                                                                {
                                                                                                    stop(exception);
                                                                                                }
                                                                                            }
                                                                                            else
                                                                                            {
                                                                                                stop(asyncResponse.cause());
                                                                                            }
                                                                                        });
                                                                                    }
                                                                                    else
                                                                                    {
                                                                                        LOGGER.fatal("something went wrong with config db service..");

                                                                                        LOGGER.info("stopping config db service...");
                                                                                    }
                                                                                });
                                                                    }
                                                                    else
                                                                    {
                                                                        LOGGER.error(result.cause());
                                                                    }
                                                                }
                                                                catch (Exception exception)
                                                                {
                                                                    LOGGER.error(exception);
                                                                }
                                                            });
                                                });

                                            }
                                            else
                                            {
                                                LOGGER.error(asyncResult.cause());

                                                System.exit(0);
                                            }
                                        });
                                    }
                                });
                            }
                            else
                            {
                                stop(resultHandler.cause());
                            }
                        });
            }
            else
            {
                stop("motadata observer server is not reachable...");
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

