package com.mindarray.store;

import com.mindarray.GlobalConstants;
import com.mindarray.agent.AgentConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.api.APIConstants;
import com.mindarray.api.Discovery;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.db.ConfigDBConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

import static com.mindarray.agent.AgentConstants.AGENT;
import static com.mindarray.api.APIConstants.*;
import static com.mindarray.api.Agent.AGENT_CONFIGS;
import static com.mindarray.api.Agent.AGENT_UUID;

public class AgentConfigStore extends AbstractConfigStore
{
    private static final Logger LOGGER = new Logger(AgentConfigStore.class, GlobalConstants.MOTADATA_STORE, "Agent Config Store");

    private static final AgentConfigStore STORE = new AgentConfigStore();

    private final Map<String, Long> itemsByUUID = new ConcurrentHashMap<>();

    private AgentConfigStore()
    {
        super(ConfigDBConstants.COLLECTION_AGENT, LOGGER, false, new ArrayList<>()
        {{
            add(new HashMap<>()
            {{
                put(REFERENCE_ENTITY, APIConstants.Entity.DISCOVERY);
                put(REFERENCE_ENTITY_PROPERTY, Discovery.DISCOVERY_AGENTS);
                put(REFERENCE_ENTITY_STORE, ConfigStore.DISCOVERY);
                put(REFERENCE_ENTITY_PROPERTY_TYPE, APIConstants.ReferenceEntityPropertyType.MULTI_VALUE);
            }});

            add(new HashMap<>()
            {{
                put(REFERENCE_ENTITY, APIConstants.Entity.OBJECT);
                put(REFERENCE_ENTITY_STORE, ConfigStore.OBJECT);
                put(REFERENCE_ENTITY_CONTEXT_PROP_KEY, AIOpsObject.OBJECT_CATEGORY);
                put(REFERENCE_ENTITY_CONTEXT_PROP_VALUE, NMSConstants.Category.SERVICE_CHECK.getName());
                put(REFERENCE_ENTITY_CONTEXT_PROP_CONDITION, AIOpsObject.OBJECT_AGENT);
                put(REFERENCE_ENTITY_PROPERTY_TYPE, ReferenceEntityPropertyType.CONTEXT_VALUE);
            }});

        }});
    }

    public static AgentConfigStore getStore()
    {
        return STORE;
    }

    private void init()
    {
        itemsByUUID.clear();

        items.values().stream().filter(item -> item.getString(AGENT_UUID) != null)
                .collect(Collectors.groupingBy(item -> item.getString(AGENT_UUID),
                        Collectors.mapping(item -> item.getLong(GlobalConstants.ID), Collectors.toList())))
                .forEach((key, value) ->
                        itemsByUUID.put(key, value.get(0)));

    }

    @Override
    public Future<Void> addItem(long id)
    {
        var promise = Promise.<Void>promise();

        super.addItem(id).onComplete(handler ->
        {
            if (handler.succeeded())
            {
                itemsByUUID.put(getItem(id).getString(AGENT_UUID), id);
            }

            promise.complete();
        });

        return promise.future();
    }

    @Override
    public void deleteItem(long id)
    {
        if (items.containsKey(id))
        {
            super.deleteItem(id);

            init();
        }
    }

    @Override
    public void deleteItems(JsonArray ids)
    {
        super.deleteItems(ids);

        init();
    }

    public String getAgentUUID(long id)
    {
        return existItem(id) ? items.get(id).getString(AGENT_UUID) : null;
    }

    public Long getAgentId(String uuid)
    {
        return itemsByUUID.containsKey(uuid) ? itemsByUUID.get(uuid) : CommonUtil.getLong(GlobalConstants.NOT_AVAILABLE);
    }

    @Override
    public Future<Void> initStore()
    {

        var promise = Promise.<Void>promise();

        super.initStore().onComplete(result ->
        {
            if (result.succeeded())
            {
                try
                {
                    init();

                    promise.complete();
                }

                catch (Exception exception)
                {
                    promise.fail(exception);

                    LOGGER.warn("failed to init agent config store...");

                    LOGGER.error(exception);
                }
            }

            else
            {
                promise.fail(result.cause());
            }
        });

        return promise.future();
    }

    public int getProvisionedItems()
    {
        return items.size();
    }

    public int getProvisionedMetricAgents()
    {
        var items = 0;

        for (var item : this.items.entrySet())
        {
            if (item.getValue().containsKey(AGENT_CONFIGS))
            {
                var configs = new JsonObject(item.getValue().getString(AGENT_CONFIGS));

                if (GlobalConstants.YES.equalsIgnoreCase(configs.getJsonObject(AGENT).getString(AgentConstants.METRIC_AGENT_STATUS)) && RemoteEventProcessorConfigStore.getStore().getItemByValue(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, configs.getJsonObject(AgentConstants.AGENT).getString(AGENT_UUID)) == null)
                {
                    items++;
                }
            }
        }
        return items;
    }

    public void updateItem(long id, JsonObject item)
    {
        items.put(id, item);
    }
}

