import javax.annotation.Nullable;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.SESSION_ID;
import static com.mindarray.eventbus.EventBusConstants.*;

@ExtendWith(VertxExtension.class)
@Execution(ExecutionMode.CONCURRENT)
@io.vertx.junit5.Timeout(1000 * 60)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class TestOtherRunbook {

    private static MessageConsumer<JsonObject> messageConsumer;
    private static final JsonObject CONTEXTS = new JsonObject();
    private static final Logger LOGGER = new Logger(TestOtherRunbook.class, MOTADATA_RUNBOOK, "Other Runbook Test");

    @BeforeEach
    void beforeEach(VertxTestContext testContext, TestInfo testInfo)
    {
        LOGGER.info(String.format("running test case %s", testInfo.getTestMethod().get().getName()));

        if (messageConsumer != null)
        {
            messageConsumer.unregister(result -> testContext.completeNow());
        }
        else
        {
            testContext.completeNow();
        }
    }

    @Test
    @Timeout(3 * 1000 * 60)
    void testRunbookInvalidTarget(VertxTestContext testContext)
    {
        var context = TestConstants.prepareParams("testCreatePowershellAvailabilityRunbookPlugin");

        Assertions.assertNotNull(context);

        TestConstants.prepareRunbookTestContext(context);

        var objects = ObjectConfigStore.getStore().flatItems(AIOpsObject.OBJECT_IP, "172.16.8.165", ID);

        Assertions.assertNotNull(objects);

        Assertions.assertFalse(objects.isEmpty());

        context.put("testcase.name", "testRunbookInvalidTarget");

        context.put(ID, objects.getLong(0)).put(RunbookPlugin.RUNBOOK_PLUGIN_ENTITIES, new JsonArray().add(objects.getLong(0))).put(EVENT_ID, CommonUtil.newEventId());

        context.getJsonObject(RunbookPlugin.RUNBOOK_PLUGIN_CONTEXT);

        assertTestResult(objects.getLong(0), STATUS_FAIL, String.format(ErrorMessageConstants.RUNBOOK_EXECUTION_FAILED, ErrorMessageConstants.CONNECTION_FAILED), ErrorCodes.ERROR_CODE_RUNBOOK_PLUGIN_TEST, testContext, context, STATUS_UP, "testRunbookInvalidTarget");
    }

