    {
        var context = RunbookPluginConfigStore.getStore().getItem(10000000000003L);

        Assertions.assertNotNull(context);

        Assertions.assertFalse(context.isEmpty());

        var object = ObjectConfigStore.getStore().flatItems(AIOpsObject.OBJECT_IP, "172.16.10.1", ID);

        Assertions.assertNotNull(object);

        Assertions.assertFalse(object.isEmpty());

        context.put(RunbookPlugin.RUNBOOK_PLUGIN_ENTITIES, object);

        TestConstants.assertRunbookRunEventTestResult(LOGGER, testContext, context, STATUS_SUCCEED, null, ErrorCodes.ERROR_CODE_SUCCESS);
    }

    @Test
