package com.mindarray.ha;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.*;
import io.vertx.core.json.JsonObject;

import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;

public class Datastore
{
    private static final Logger LOGGER = new Logger(Datastore.class, GlobalConstants.MOTADATA_DATASTORE, "Datastore");
    private final String path;
    private final Map<String, EventFile> eventFiles; //store all files by time order (milliseconds)
    private final long maxBufferLength = MotadataConfigUtil.getDatastoreWriterMaxBufferMB() * (1048576);
    private final Map<Long, String> eventPartitions; //store all files by time order (milliseconds)
    private byte[] bytes;

    public Datastore(String path)
    {
        this.path = path;

        eventFiles = new LinkedHashMap<>();

        eventPartitions = new LinkedHashMap<>();

        switch (MotadataConfigUtil.getDeploymentType())
        {
            case 0:
            {
                this.bytes = new byte[32 * 1024];

                break;
            }
            case 1:
            {
                this.bytes = new byte[64 * 1024];

                break;
            }
            case 2:
            {
                this.bytes = new byte[512 * 1024];

                break;
            }
            default:
            {
                this.bytes = new byte[32 * 1024];
            }
        }

    }

    protected void load() throws Exception
    {
        try
        {
            var files = new File(path).listFiles();

            if (files != null)
            {
                Arrays.sort(files);

                var offsets = new HashMap<String, Long>();

                var bookmark = new File(path + GlobalConstants.PATH_SEPARATOR + "bookmarks");

                if (bookmark.exists())
                {
                    var value = Files.readString(bookmark.toPath(), StandardCharsets.UTF_8);

                    if (CommonUtil.isNotNullOrEmpty(value))
                    {
                        for (var entry : new JsonObject(value))
                        {
                            offsets.put(entry.getKey(), CommonUtil.getLong(entry.getValue().toString().split("_")[0]));
                        }
                    }
                }

                Arrays.stream(files).filter(file -> file.getName().endsWith(".dat")).forEach(file ->
                {
                    try
                    {
                        var tokens = file.getName().split(GlobalConstants.DASH_SEPARATOR);

                        var eventFile = file.getName().split(GlobalConstants.DOT_SEPARATOR_ESCAPE)[0];

                        var fileOutputStream = new FileOutputStream(file, true);

                        var fileInputStream = new FileInputStream(file);

                        var offset = offsets.getOrDefault(eventFile, 0L);

                        fileInputStream.skip(offset);

                        eventFiles.put(eventFile, new EventFile(new BufferedOutputStream(fileOutputStream, bytes.length), fileInputStream, fileOutputStream, new AtomicLong(offset)));

                        eventPartitions.put(CommonUtil.getLong(tokens[0]), eventFile);
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                });
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void put(byte[] bufferBytes, String eventType) throws Exception
    {
        try
        {
            var timestamp = ByteUtil.readLongValue(bufferBytes);

            bufferBytes = CodecUtil.compress(bufferBytes);

            if (bufferBytes.length + 4 > this.bytes.length)
            {
                this.bytes = new byte[bufferBytes.length + 4]; //if buffer bytes is larger than existing bytes then we must need to expand for the future read purpose...
            }

            if (!eventPartitions.containsKey(timestamp))
            {
                var currentEventPart = timestamp + GlobalConstants.DASH_SEPARATOR + 1;

                var file = new File(path + GlobalConstants.PATH_SEPARATOR + currentEventPart + ".dat");

                var fileOutputStream = new FileOutputStream(file, true);

                eventFiles.put(currentEventPart, new EventFile(new BufferedOutputStream(fileOutputStream, this.bytes.length), new FileInputStream(file), fileOutputStream, new AtomicLong(0L)));

                eventPartitions.put(timestamp, currentEventPart);

                Bootstrap.vertx().eventBus().send(eventType, currentEventPart);
            }
            else
            {
                if (eventFiles.get(eventPartitions.get(timestamp)).fileOutputStream.getChannel().position() + bufferBytes.length + 4 > maxBufferLength)
                {
                    var currentEventPart = eventPartitions.get(timestamp);

                    LOGGER.warn("Current partition exceeded maximum Limit, so now creating new partition::" + currentEventPart);

                    currentEventPart = timestamp + GlobalConstants.DASH_SEPARATOR + (CommonUtil.getInteger(currentEventPart.split(GlobalConstants.DOT_SEPARATOR_ESCAPE)[0].split(GlobalConstants.DASH_SEPARATOR)[1]) + 1);

                    var file = new File(path + GlobalConstants.PATH_SEPARATOR + currentEventPart + ".dat");

                    var fileOutputStream = new FileOutputStream(file, true);

                    eventFiles.put(currentEventPart, new EventFile(new BufferedOutputStream(fileOutputStream, this.bytes.length), new FileInputStream(file), fileOutputStream, new AtomicLong(0L)));

                    eventPartitions.put(timestamp, currentEventPart);

                    Bootstrap.vertx().eventBus().send(eventType, currentEventPart);
                }
            }

            var eventFile = eventFiles.get(eventPartitions.get(timestamp));

            ByteUtil.writeInt(this.bytes, bufferBytes.length, 0);

            eventFile.bufferedOutputStream.write(bytes, 0, 4);

            eventFile.bufferedOutputStream.write(bufferBytes, 0, bufferBytes.length);

            eventFile.bufferedOutputStream.flush();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    protected void get(JsonObject event)
    {
        try
        {
            var bufferBytes = event.getBinary(EventBusConstants.EVENT_CONTEXT);

            var eventFile = this.eventFiles.get(event.getString(DatastoreConstants.BATCH_FILE));

            if (bufferBytes.length == eventFile.fileInputStream.read(bufferBytes, 0, bufferBytes.length)) //means invalid file ... delete it skip to next file.
            {
                eventFile.offset.addAndGet(bufferBytes.length); //mark read position
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void saveBookmarks()
    {
        var bookmarks = new JsonObject();

        eventFiles.forEach((key, value) -> bookmarks.put(key, value.offset.get()));

        Bootstrap.vertx().fileSystem().writeFileBlocking(path + GlobalConstants.PATH_SEPARATOR + "bookmarks", bookmarks.toBuffer());

    }

    protected void close()
    {
        try
        {
            for (var iterator = eventFiles.entrySet().iterator(); iterator.hasNext(); )
            {
                var entry = iterator.next();

                entry.getValue().fileInputStream.close();

                entry.getValue().bufferedOutputStream.close();

                entry.getValue().fileOutputStream.close();

                iterator.remove();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

    }

    protected void close(String fileName) throws Exception
    {
        var eventFile = eventFiles.remove(fileName);

        eventFile.fileInputStream.close();

        eventFile.bufferedOutputStream.close();

        eventFile.fileOutputStream.close();

        eventPartitions.remove(CommonUtil.getLong(fileName.split(GlobalConstants.DASH_SEPARATOR)[0]));

        Bootstrap.vertx().fileSystem().delete(path + GlobalConstants.PATH_SEPARATOR + fileName + ".dat");
    }

    private
    record EventFile(BufferedOutputStream bufferedOutputStream, FileInputStream fileInputStream,
                     FileOutputStream fileOutputStream, AtomicLong offset)
    {

    }

}

