                    user.principal()
                            .put(OAuthUtil.REFRESH_TOKEN, context.getString(OAuthUtil.REFRESH_TOKEN))
                            .put(OAuthUtil.TOKEN_TYPE, context.getString(OAuthUtil.TOKEN_TYPE));

                    oauth2.refresh(user)
                            .onComplete(response ->
