		operation := consts.BlankString

		if variables.Contains("operation") {

			if variables.GetMotadataStringValue("operation").ToLowerNative() == "start" {

				operation = "Start-VM"

			} else if variables.GetMotadataStringValue("operation").ToLowerNative() == "stop" {

				operation = "Stop-VM -force"

			} else {

				return nil, errors.New(fmt.Sprintf("Invalid Operation %s", variables.GetStringValue("operation")))
