		}

		var commands motadatatypes.MotadataStringList

		if variables.Contains("vms") {

			vms := variables.GetMotadataStringValue("vms")

			for _, vm := range vms.Split(",") {

				commands = append(commands, fmt.Sprintf("Get-VM -Name %s | %s", vm, operation))
			}

			return commands, nil

		} else if context.Contains(consts.Objects) && len(context.GetSliceValue(consts.Objects)) > 0 {

			for _, object := range context.GetSliceValue(consts.Objects) {

				vm := motadatatypes.ToMap(object)

				if vm.GetMotadataStringValue(consts.ObjectName).IsNotEmpty() {

					commands = append(commands, fmt.Sprintf("Get-VM -Name %s | %s", vm.GetMotadataStringValue(consts.ObjectName), operation))
				}
			}

			return commands, nil

		} else {

			return nil, errors.New("No Object(s) found")
		}

	} else {

		return nil, errors.New("No Variable(s) found")
	}
