func run(result, context motadatatypes.MotadataMap) {

	client := &winrmclient.WinRMClient{}

	client.GetConnection(context)

	result[consts.Status] = consts.StatusFail

	defer cleanUp(client, result)

	if client.Init() {

		var processes []motadatatypes.MotadataString

		count := 10 // default

		if context.Contains(consts.RunbookPluginVariables) && context.GetMapValue(consts.RunbookPluginVariables).Contains("count") {

			count = context.GetMapValue(consts.RunbookPluginVariables).GetIntValue("count")
		}

		command := motadatatypes.MotadataString(fmt.Sprintf("(Get-Counter '\\Process(*)\\%% Processor Time').CounterSamples | Sort cookedvalue -Desc | Select -first %d | Format-list Path", count))

		output := client.ExecuteCommand(command)

		if output.IsNotEmpty() {

			for _, token := range output.Split(consts.NewLineRegexPattern + consts.NewLineRegexPattern) {

				if token.HasPrefix("Path") {

					processes = append(processes, token.Split("(")[1].Split(")")[0].TrimSpace())
				}
			}

			query := motadatatypes.MotadataString(consts.BlankString)

			for _, process := range processes {

				query += motadatatypes.MotadataString("(Get-Counter '\\Process(@@@)\\ID Process','\\Process(@@@)\\% Processor Time','\\Process(@@@)\\Thread Count','\\Process(@@@)\\Working Set','\\Process(@@@)\\IO Data Bytes/sec','\\Process(@@@)\\IO Data Operations/sec','\\Process(@@@)\\Virtual Bytes' -ErrorAction SilentlyContinue).countersamples | Format-List  -Property Path,Cookedvalue;").ReplaceAll("@@@", process)
			}

			output = client.ExecuteCommand(query + "Get-WmiObject Win32_Process | Select-Object processid, commandline, name | Format-List; Get-WmiObject win32_processor | Format-List  -Property numberoflogicalprocessors")

			if output.IsNotEmpty() {

				processes := setProcessMetrics(output.Split(consts.NewLineRegexPattern + consts.NewLineRegexPattern + consts.NewLineRegexPattern + consts.NewLineRegexPattern))

				if motadatatypes.IsNotEmptyMapSlice(processes) {

					result[consts.Result] = make(motadatatypes.MotadataMap)

					result.GetMapValue(consts.Result)[consts.Process] = processes

					result[consts.Status] = consts.StatusSucceed
				}
			}
		}
	}

	if len(client.GetErrors()) > 0 {

		result[consts.Errors] = append(result.GetStringMapSliceValue(consts.Errors), client.GetErrors()...)

	} else if result.GetStringValue(consts.Status) == consts.StatusFail {

		result[consts.Errors] = append(result.GetStringMapSliceValue(consts.Errors), motadatatypes.MotadataStringMap{

			consts.ErrorCode: consts.ErrorCodeNoItemFound,

			consts.Message: "No Process(s) found",
		})
	}
}

func setProcessMetrics(metrics []motadatatypes.MotadataString) []motadatatypes.MotadataMap {

	var processes []motadatatypes.MotadataMap

	if motadatatypes.IsNotEmptyStringSlice(metrics) {

		logicalProcessors := motadatatypes.MotadataINT(0)

		for _, token := range metrics[len(metrics)-1].TrimSpace().Split(consts.NewLineRegexPattern + consts.NewLineRegexPattern) {

			if token.IsNotEmpty() && token.Split(":")[0].Trim(consts.SpaceSeparator).Contains("numberoflogicalprocessors") {

				logicalProcessors = logicalProcessors + token.Split(":")[1].TrimSpace().ToINT()
			}
		}

		processNames := make(motadatatypes.MotadataStringMap)

		processIds := make(motadatatypes.MotadataMap)

		for index := range metrics {

			if metrics[index].HasPrefix("Path") {

				counterValues := metrics[index].TrimSpace().ReplaceAll("CookedValue :", consts.BlankString).Split(consts.NewLineRegexPattern)

				for index := range counterValues {

					if counterValues[index].HasPrefix("Path") {

						value := counterValues[index+1].TrimSpace()

						processName := counterValues[index].SplitN(":", 2)[1].Split("(")[1].Split(")")[0].ToString()

						if counterValues[index].Contains("id process") && !processIds.Contains(value.ToString()) {

							processNames[processName] = value.ToString()

							processIds[value.ToString()] = make(motadatatypes.MotadataMap)

							processIds.GetMapValue(value.ToString())[consts.ProcessId] = value.ToInt()

							processIds.GetMapValue(value.ToString())[consts.Status] = consts.StatusUp

						} else if counterValues[index].Contains("processor time") && processNames.Contains(processName) {

							processIds.GetMapValue(processNames[processName])[consts.ProcessCPUPercent] = value.ToFloat64() / motadatatypes.MotadataFloat64(logicalProcessors)

						} else if counterValues[index].Contains("thread count") && processNames.Contains(processName) {

							processIds.GetMapValue(processNames[processName])[consts.ProcessThreads] = value.ToInt()

						} else if counterValues[index].Contains("working set") && processNames.Contains(processName) {

							processIds.GetMapValue(processNames[processName])[consts.ProcessMemoryBytes] = value.ToInt()

						} else if counterValues[index].Contains("virtual bytes") && processNames.Contains(processName) {

							processIds.GetMapValue(processNames[processName])[consts.ProcessVirtualMemoryBytes] = value.ToInt()
						}
					}
				}

			} else if metrics[index].HasPrefix("processid") {

				for _, token := range metrics[index].Split(consts.NewLineRegexPattern + consts.NewLineRegexPattern) {

					tokens := token.SplitN(consts.NewLineRegexPattern, 3)

					if tokens[0].HasPrefix("processid") && processIds.Contains(tokens[0].SplitN(":", 2)[1].TrimSpace().ToString()) {

						processIds.GetMapValue(tokens[0].Split(":")[1].TrimSpace().ToString())[consts.ProcessName] = tokens[2].SplitN(":", 2)[1].TrimSpace()

						splittedTokens := tokens[1].SplitN(":", 2)

						if len(splittedTokens) > 1 {

							processIds.GetMapValue(tokens[0].Split(":")[1].TrimSpace().ToString())[consts.Process] = tokens[2].SplitN(":", 2)[1].TrimSpace() + "|" + splittedTokens[1].TrimSpace()

							processIds.GetMapValue(tokens[0].Split(":")[1].TrimSpace().ToString())[consts.ProcessCommand] = splittedTokens[1].TrimSpace()

						} else if len(splittedTokens) == 1 {

							processIds.GetMapValue(tokens[0].Split(":")[1].TrimSpace().ToString())[consts.Process] = tokens[2].SplitN(":", 2)[1].TrimSpace()

							processIds.GetMapValue(tokens[0].Split(":")[1].TrimSpace().ToString())[consts.ProcessCommand] = consts.BlankString
						}

						processes = append(processes, processIds.GetMapValue(tokens[0].Split(":")[1].TrimSpace().ToString()))
					}
				}
			}
		}
	}

	return processes
}

