func buildCommand(context motadatatypes.MotadataMap) (motadatatypes.MotadataString, error) {

	if variables := context.GetMapValue(consts.RunbookPluginVariables); variables.Contains("operation") {

		operation := variables.GetMotadataStringValue("operation")

		var serviceNames = motadatatypes.MotadataString(consts.BlankString)

		if variables.Contains("service.names") {

			serviceNames = variables.GetMotadataStringValue("service.names")

		} else if context.Contains(consts.Objects) && len(context.GetSliceValue(consts.Objects)) > 0 {

			for _, object := range context.GetSliceValue(consts.Objects) {

				object := motadatatypes.ToMap(object)

				if object.Contains(consts.ObjectName) {

					serviceNames += object.GetMotadataStringValue(consts.ObjectName) + ","
				}
			}
		}

		if serviceNames.Trim(",") != consts.BlankString {

			if operation.ToLowerNative() == consts.OperationStart {

				return "Start-Service -Name " + serviceNames.Trim(","), nil

			} else if operation.ToLowerNative() == consts.OperationStop {

				return "Stop-Service -Name " + serviceNames.Trim(","), nil

			} else {

				return consts.BlankString, errors.New(fmt.Sprintf("invalid operation type %s", operation))
			}

		} else {

			return consts.BlankString, errors.New("Service name not specified")
		}

	} else {

		return consts.BlankString, errors.New("Service operation not specified")
	}
}

