class ESXiVMPowerOperationRunbookPlugin:

    def run(self, context):

        errors = []

        result = {Constant.STATUS: Constant.STATUS_FAIL}

        vmware_client = None

        succeeded = False

        try:

            objects = Util.get_objects(context, "vms")

            if objects is not None and len(objects) > 0:

                if context.get(Constant.RUNBOOK_PLUGIN_VARIABLES) is not None and context.get(
                        Constant.RUNBOOK_PLUGIN_VARIABLES).get("operation") is not None:

                    operation = context.get(Constant.RUNBOOK_PLUGIN_VARIABLES).get("operation")

                    vmware_client = VMwareClient().get_connection(context=context)

                    if vmware_client is not None and vmware_client.init():

                        client = vmware_client.get_client()

                        service_content = client.RetrieveContent()

                        container = service_content.rootFolder

                        # The recursive flag is set to True while creating the container view
                        container_view = service_content.viewManager.CreateContainerView(container,
                                                                                         [vim.VirtualMachine],
                                                                                         True)
                        vms = container_view.view

                        container_view.Destroy()

                        if vms is not None:

                            for vm in vms:

                                try:

                                    if vm.summary.config.name in objects:
                                        if operation == 'start':
                                            vm.PowerOn()
                                            succeeded = True

                                        elif operation == 'stop':
                                            vm.PowerOff()
                                            succeeded = True

                                        else:
                                            errors.append({
                                                Constant.MESSAGE: "Invalid operation: {}, Operation should be start or stop".format(
                                                    operation),

                                                Constant.ERROR_CODE: Constant.ERROR_CODE_BAD_REQUEST
                                            })
                                            return result

                                except Exception:

                                    errors.append({
                                        Constant.MESSAGE: "Failed to {} VM {}".format(operation, vm),
                                        Constant.ERROR: str(Logger.get_stack_trace()),
                                        Constant.ERROR_CODE: Constant.ERROR_CODE_INTERNAL_ERROR
                                    })

                            if succeeded:
