                    if succeeded is not True:
                        errors.append({
                            Constant.MESSAGE: "No VM(s) found",
                            Constant.ERROR_CODE: Constant.ERROR_CODE_NO_ITEM_FOUND
                        })
                else:
                    errors.append({
                        Constant.MESSAGE: "No vm operation specified",
                        Constant.ERROR_CODE: Constant.ERROR_CODE_BAD_REQUEST
                    })

            else:

                errors.append({
                    Constant.MESSAGE: "No Object(s) found",
