	if err != nil {

		result[consts.Errors] = []motadatatypes.MotadataStringMap{
			{
				consts.ErrorCode: consts.ErrorCodeBadRequest,
				consts.Message:   err.Error(),
			},
		}

	} else {

		if client.Init() {

			output := client.ExecuteCommand(command)

			if output.IsEmpty() {

				result[consts.Status] = consts.StatusSucceed
			}
		}

		if len(client.GetErrors()) > 0 {

			result[consts.Status] = consts.StatusFail

			result[consts.Errors] = client.GetErrors()

		} else if result.GetStringValue(consts.Status) == consts.StatusFail {

			result[consts.Errors] = []motadatatypes.MotadataStringMap{
