func buildCommand(context motadatatypes.MotadataMap, client *winrmclient.WinRMClient) (motadatatypes.MotadataString, error) {

	if context.Contains(consts.RunbookPluginVariables) {

		variables := context.GetMapValue(consts.RunbookPluginVariables)

		if variables.Contains("process.group") && variables.Contains("process.name") {

			return consts.BlankString, errors.New("process group & process name cannot be passed at same time")
		}

		if variables.Contains("process.group") {

			command := "Get-Process " + variables.GetMotadataStringValue("process.group") + " | Stop-Process -Force"

			return command, nil

		} else if variables.Contains("process.name") {

			if client.Init() {

				output := client.ExecuteCommand("Get-WmiObject Win32_Process | Select-Object name, processid, CommandLine | Format-List")

				if output.IsNotEmpty() {

					pids := strings.Builder{}

					tokens := output.Split(consts.NewLineRegexPattern + consts.NewLineRegexPattern)

					if variables.Contains("process.command.line") {

						for _, token := range tokens {

							splittedTokens := token.ReplaceAll("CommandLine :", consts.BlankString).SplitN(consts.NewLineRegexPattern, 3)

							if len(splittedTokens) == 3 &&
								splittedTokens[0].Split(":")[1] == variables.GetMotadataStringValue("process.name") &&
								splittedTokens[2].Contains(variables.GetStringValue("process.command.line")) {

								pids.WriteString(splittedTokens[1].Split(":")[1].TrimSpace().ToString())

								pids.WriteString(",")
							}
						}

					} else {

						for _, token := range tokens {

							splittedTokens := token.ReplaceAll("CommandLine :", consts.BlankString).SplitN(consts.NewLineRegexPattern, 3)

							if splittedTokens[0].Split(":")[1] == variables.GetMotadataStringValue("process.name") {

								pids.WriteString(splittedTokens[1].Split(":")[1].TrimSpace().ToString())

								pids.WriteString(",")
							}
						}
					}

					if len(pids.String()) > 0 {

						return "Stop-Process -Force -Id " + motadatatypes.MotadataString(pids.String()).Trim(","), nil

					} else {

						return consts.BlankString, errors.New("No Process(s) qualified")
					}

				} else {

					return consts.BlankString, errors.New("Internal Error")
				}

			} else {

				return consts.BlankString, errors.New("Internal Error")
			}

		} else {

			return consts.BlankString, errors.New("Process name not specified")
		}

	} else if context.Contains(consts.Objects) && len(context.GetSliceValue(consts.Objects)) > 0 {

		pids := strings.Builder{}

		for _, object := range context.GetSliceValue(consts.Objects) {

			object := motadatatypes.ToMap(object)

			if object.Contains(consts.ObjectName) {

				pids.WriteString(object.GetStringValue(consts.ObjectName)) //objectName will always be a PID.

				pids.WriteString(",")
			}
		}

		return "Stop-Process -Force -Id " + motadatatypes.MotadataString(pids.String()).Trim(","), nil

	} else {

		return consts.BlankString, errors.New("Process name not specified")
	}
}

