func run(result, context motadatatypes.MotadataMap) {

	output := context.GetMotadataStringValue(consts.Result)

	var processes []motadatatypes.MotadataMap

	result[consts.Status] = consts.StatusFail

	defer func() {

		if r := recover(); r != nil {

			result[consts.Errors] = []motadatatypes.MotadataStringMap{
				{
					consts.ErrorCode: consts.ErrorCodeInternalError,
					consts.Message:   "Invalid Result",
					consts.Error:     fmt.Sprintf("%v", r),
				},
			}
		}
	}()

	if output.IsNotEmpty() {

		for _, row := range output.Split(consts.NewLineSeparator) {

			tokens := motadatatypes.MotadataString(regexp.MustCompile(`\s+`).ReplaceAllString(row.ToString(), consts.SpaceSeparator)).SplitN(consts.SpaceSeparator, 10)

			if len(tokens) == 10 {

				process := make(motadatatypes.MotadataMap)

				process[consts.Status] = consts.StatusUp

				process[consts.Process] = tokens[0].TrimSpace() + "|" + tokens[9].TrimSpace()

				process[consts.ProcessId] = tokens[1].TrimSpace().ToInt()

				process[consts.ProcessUser] = tokens[2].TrimSpace()

				process[consts.ProcessCPUPercent] = tokens[3].TrimSpace().ToFloat64()

				process[consts.ProcessMemoryPercent] = tokens[4].TrimSpace().ToFloat64()

				process[consts.ProcessVirtualMemoryBytes] = motadatatypes.MotadataKB(tokens[5].TrimSpace().ToFloat64()).ToBytes()

				process[consts.ProcessMemoryBytes] = motadatatypes.MotadataKB(tokens[6].TrimSpace().ToFloat64()).ToBytes()

				setProcessUptimeMetrics(process, tokens[7].TrimSpace())

				process[consts.ProcessThreads] = tokens[8].TrimSpace().ToInt()

				process[consts.ProcessCommand] = tokens[9].TrimSpace()

				processes = append(processes, process)
			}
		}
	}

	if motadatatypes.IsNotEmptyMapSlice(processes) {

		result[consts.Result] = make(motadatatypes.MotadataMap)

		result.GetMapValue(consts.Result)[consts.Process] = processes

		result[consts.Status] = consts.StatusSucceed

	} else {

		result[consts.Errors] = []motadatatypes.MotadataStringMap{
			{
				consts.ErrorCode: consts.ErrorCodeNoItemFound,
				consts.Message:   "No Result found",
			},
		}
	}
}

func setProcessUptimeMetrics(process motadatatypes.MotadataMap, token motadatatypes.MotadataString) {

	days := motadatatypes.MotadataINT(0)

	hours := motadatatypes.MotadataINT(0)

	minutes := motadatatypes.MotadataINT(0)

	seconds := motadatatypes.MotadataINT(0)

	if token.Contains("-") {

		tokens := token.Split("-")

		days = tokens[0].ToINT()

		token = tokens[1]
	}

	tokens := token.Split(":")

	if len(tokens) == 3 {

		hours = tokens[0].ToINT()

		minutes = tokens[1].ToINT()

		seconds = tokens[2].ToINT()

	} else if len(tokens) == 2 {

		minutes = tokens[0].ToINT()

		seconds = tokens[1].ToINT()

	} else if len(tokens) == 1 {

		seconds = tokens[0].ToINT()
	}

	process[consts.ProcessUptimeSeconds] = ((days*24+hours)*60+minutes)*60 + seconds

	process[consts.ProcessUptime] = motadatatypes.MotadataTime(process.GetINTValue(consts.ProcessUptimeSeconds)).ToString()
