func run(result motadatatypes.MotadataMap, context motadatatypes.MotadataMap) {

	client := &sshclient.SSHClient{}

	client.GetConnection(context)

	result[consts.Status] = consts.StatusFail

	defer cleanUp(client, result)

	command, processes, err := buildCommand(context)

	if err != nil {

		result[consts.Errors] = []motadatatypes.MotadataStringMap{
			{
				consts.ErrorCode: consts.ErrorCodeBadRequest,
				consts.Message:   err.Error(),
			},
		}
		return
	}

	if client.Init() {

		if output, valid := client.ExecuteCommand(command); valid {

			pids := motadatatypes.MotadataString(consts.BlankString)

			for _, token := range output.Split(consts.NewLineSeparator) {

				pattern := motadatatypes.MotadataString(regexp.MustCompile(`\s+`).ReplaceAllString(token.ToString(), consts.SpaceSeparator))

				if processes.Contains(pattern.SplitN(consts.SpaceSeparator, 3)[1].TrimSpace() + "|" + pattern.SplitN(consts.SpaceSeparator, 3)[2].TrimSpace()) {

					pids += pattern.SplitN(consts.SpaceSeparator, 2)[0] + consts.SpaceSeparator
				}
			}

			if pids.TrimSpace().IsNotEmpty() {

				if output, _ := client.ExecuteCommand("sudo kill -9 " + pids.TrimSpace()); !output.IsNotEmpty() {

					result[consts.Status] = consts.StatusSucceed
				}

			} else {

				result[consts.Errors] = []motadatatypes.MotadataStringMap{
					{
						consts.ErrorCode: consts.ErrorCodeNoItemFound,
						consts.Message:   "No Process(s) qualified",
					},
				}
			}
		}
	}

	if len(client.GetErrors()) > 0 {

		result[consts.Errors] = client.GetErrors()

		result[consts.Status] = consts.StatusFail

	} else if result.GetStringValue(consts.Status) == consts.StatusFail {

		result[consts.Errors] = []motadatatypes.MotadataStringMap{
			{
				consts.ErrorCode: consts.ErrorCodeNoItemFound,
				consts.Message:   "No Process(s) found",
			},
		}
	}
}

func buildCommand(context motadatatypes.MotadataMap) (motadatatypes.MotadataString, motadatatypes.MotadataStringList, error) {

	if _, found := context[consts.RunbookPluginVariables]; found && context.GetMapValue(consts.RunbookPluginVariables).Contains("process.name") {

		processName := context.GetMapValue(consts.RunbookPluginVariables).GetMotadataStringValue("process.name")

		return motadatatypes.MotadataString(fmt.Sprintf("ps -eo pid,fname,args | egrep -e '%s'", processName.Split("|")[0])), append(motadatatypes.MotadataStringList{}, processName.ToString()), nil

	} else if context.Contains(consts.Objects) && len(context.GetSliceValue(consts.Objects)) > 0 {

		pids := strings.Builder{}

		var processes motadatatypes.MotadataStringList

		for _, object := range context.GetSliceValue(consts.Objects) {

			object := motadatatypes.ToMap(object)

			if object.Contains(consts.ObjectName) {

				processes = append(processes, object.GetStringValue(consts.ObjectName))

				pids.WriteString(object.GetMotadataStringValue(consts.ObjectName).Split("|")[0].ToString())

				pids.WriteString("|")
			}
		}

		return motadatatypes.MotadataString(fmt.Sprintf("ps -eo pid,fname,args | egrep -e '%s'", motadatatypes.MotadataString(pids.String()).Trim("|"))), processes, nil

	} else {

		return consts.BlankString, nil, errors.New("Process name not specified")
	}
}

func cleanUp(sshClient *sshclient.SSHClient, result motadatatypes.MotadataMap) {

	if r := recover(); r != nil {

		result[consts.Errors] = []motadatatypes.MotadataStringMap{
			{
				consts.ErrorCode: consts.ErrorCodeInternalError,
				consts.Message:   "Invalid Result",
				consts.Error:     fmt.Sprintf("%v", r),
			},
		}
	}

	sshClient.Destroy()
