func setProcessUptimeMetrics(process motadatatypes.MotadataMap, token motadatatypes.MotadataString) {

	days := motadatatypes.MotadataINT(0)

	hours := motadatatypes.MotadataINT(0)

	minutes := motadatatypes.MotadataINT(0)

	seconds := motadatatypes.MotadataINT(0)

	if token.Contains("-") {

		tokens := token.Split("-")

		days = tokens[0].ToINT()

		token = tokens[1]

	}

	tokens := token.Split(":")

	if len(tokens) == 3 {

		hours = tokens[0].ToINT()

		minutes = tokens[1].ToINT()

		seconds = tokens[2].ToINT()

	} else if len(tokens) == 2 {

		minutes = tokens[0].ToINT()

		seconds = tokens[1].ToINT()

	} else if len(tokens) == 1 {

		seconds = tokens[0].ToINT()
	}

	process[consts.ProcessUptimeSeconds] = ((days*24+hours)*60+minutes)*60 + seconds

	process[consts.ProcessUptime] = motadatatypes.MotadataTime(process.GetINTValue(consts.ProcessUptimeSeconds)).ToString()
