import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import io.vertx.core.net.NetClientOptions;
import io.vertx.core.net.NetSocket;
import io.vertx.core.parsetools.RecordParser;

import java.nio.charset.StandardCharsets;
import java.util.function.Consumer;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.EVENT_TOPIC;

public class TCPClient implements TransportClient
{
    private final JsonObject config;

    private final String eventType;

    private NetSocket socket;

    private Consumer<byte[]> consumer;

    private static final Logger LOGGER = new Logger(TCPClient.class, GlobalConstants.MOTADATA_EVENT_BUS, "TCP Client");

    private final String remoteEventTopic = EventBusConstants.getRemoteEventTopic(Bootstrap.bootstrapType()).split(DOT_SEPARATOR_ESCAPE,2)[1];

    public TCPClient(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EventBusConstants.EVENT_TYPE);

        consumer = bytes -> Bootstrap.vertx().eventBus().send(eventType,bytes);
    }

    @Override
    public Future<Void> connect()
    {
        var promise = Promise.<Void>promise();

        var client = Bootstrap.vertx().createNetClient(new NetClientOptions().setReconnectAttempts(5).setReconnectInterval(5000)
                .setReuseAddress(true).setReusePort(true).setTcpFastOpen(true).setTcpNoDelay(true).setTcpKeepAlive(true).setTcpCork(true)
                .setSendBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes()).setReceiveBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes()));

        client.connect(config.getInteger(PORT),config.getString(HOST))
                .onComplete(handler ->
                {
                    try
                    {
                        if (handler.succeeded())
                        {
                            socket = handler.result();

                            socket.write(Buffer.buffer(new JsonObject().put(EVENT_TOPIC,EventBusConstants.getRemoteEventTopic(Bootstrap.bootstrapType())).encode().getBytes(StandardCharsets.UTF_8)));

                            LOGGER.info(String.format("%s client is successfully connected with port %s", Bootstrap.bootstrapType(),config.getInteger(PORT)));

                            promise.complete();
                        }
                        else
                        {
                            // for APP manager. we're not failing promise , event though connection is failed.

                            LOGGER.warn(String.format("%s error while connecting :%s ",Bootstrap.bootstrapType(),handler.cause()));

                            promise.complete();
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.warn(String.format("error occurred while connecting in %s ",Bootstrap.bootstrapType()));

                        LOGGER.error(exception);

                        promise.fail(exception);
                    }
                });

        return promise.future();
    }

    @Override
    public void send(byte[] bytes)
    {
        try
        {
            if (socket != null)
            {
                socket.write(Buffer.buffer(bytes).appendString(VALUE_SEPARATOR_WITH_ESCAPE));

                if (CommonUtil.traceEnabled())
                {
                    LOGGER.trace(String.format("%s sending data to address : %s ",Bootstrap.bootstrapType(),config.getString(HOST) + ":"  + config.getInteger(PORT)));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public Future<Void> receive()
    {
        RecordParser.newDelimited(VALUE_SEPARATOR_WITH_ESCAPE,socket).handler(buffer ->
        {
            try
            {
                if (buffer != null && buffer.length() > 0)
                {
                    consumer.accept(Buffer.buffer().appendShortLE(CommonUtil.getShort(remoteEventTopic.getBytes().length)).appendBytes(remoteEventTopic.getBytes()).appendBytes(buffer.getBytes()).getBytes());

                    if (CommonUtil.traceEnabled())
                    {
                        LOGGER.trace(String.format("%s received bytes of length : %s at port : %s ",Bootstrap.bootstrapType(), buffer.length(),config.getInteger(PORT)));
                    }
                }
            }
            catch (Exception exception)
            {
                LOGGER.warn(String.format("error occurred in %s ",Bootstrap.bootstrapType()));

                LOGGER.error(exception);
            }
        });

        return Future.succeededFuture();
    }

    /**
     * @param handler
     */
    @Override
    public void registerMessageHandler(Consumer<byte[]> handler)
    {
        this.consumer = handler;
    }

    @Override
    public Future<Void> close()
    {
        try
        {
            LOGGER.info(String.format("%s client port : %s event.type : %s is closed ...",Bootstrap.bootstrapType(),config.getInteger(PORT),eventType));

            if (socket != null)
            {
                return socket.close();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture();
    }
}

