import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.io.File;

import static com.mindarray.GlobalConstants.CURRENT_DIR;
import static com.mindarray.GlobalConstants.PATH_SEPARATOR;
import static com.mindarray.eventbus.EventBusConstants.*;

public class MetricDatastoreWorker extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(MetricDatastoreWorker.class, GlobalConstants.MOTADATA_DATASTORE, "Metric Datastore Worker");
    private String eventType;
    private Datastore eventStore;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            eventType = config().getString(EventBusConstants.EVENT_TYPE);

            var createEventTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_CREATE);

            var storeDir = new File(CURRENT_DIR + PATH_SEPARATOR + EVENT_DIR + PATH_SEPARATOR + EventBusConstants.replace(eventType));

            if (!storeDir.exists())
            {
                storeDir.mkdirs();
            }

            eventStore = new Datastore(storeDir.getPath());

            eventStore.load();

            vertx.setPeriodic(30 * 1000, handler ->
            {
                try
                {
                    eventStore.saveBookmarks();
                }
                catch (Exception exception)
                {
                    LOGGER.warn(String.format("error occurred while saving bookmark %s", eventType));

                    LOGGER.error(exception);
                }
            });

            LOGGER.debug(String.format("metric datastore %s loaded...", eventType));

            vertx.eventBus().<byte[]>localConsumer(eventType, message ->
            {
                try
                {
                    eventStore.put(message.body(), createEventTopic);
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }).exceptionHandler(LOGGER::error);

            vertx.eventBus().<JsonObject>localConsumer(eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_SYNC_FLUSH), message ->
            {
                try
                {
                    var context = message.body();

                    eventStore.put(context.getBinary(EVENT_CONTEXT), createEventTopic,context.getLong(EVENT_TIMESTAMP));
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }).exceptionHandler(LOGGER::error);

            vertx.eventBus().<JsonObject>localConsumer(eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_READ), message ->
            {
                try
                {
                    eventStore.get(message.body());

                    message.reply(message.body());
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);

                    message.reply(message.body());
                }
            }).exceptionHandler(LOGGER::error);

            vertx.eventBus().<String>localConsumer(eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_PURGE), message ->
            {
                try
                {
                    eventStore.close(message.body());

                    if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace(String.format("metric datastore file %s deleted...", message.body()));
                        }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }).exceptionHandler(LOGGER::error);

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            eventStore.saveBookmarks();

            eventStore.close();

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            LOGGER.fatal(String.format("failed to stop event engine helper %s...", eventType));

            promise.fail(exception);

        }
    }
}

