package com.mindarray.discovery;

import com.mindarray.*;
import com.mindarray.api.Discovery;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.store.DiscoveryConfigStore;
import com.mindarray.store.SNMPDeviceCatalogConfigStore;
import com.mindarray.util.CodecUtil;
import com.mindarray.util.Logger;
import io.github.artsok.RepeatedIfExceptionsTest;
import io.vertx.core.eventbus.MessageConsumer;
import io.vertx.core.json.JsonObject;
import io.vertx.junit5.Timeout;
import io.vertx.junit5.VertxExtension;
import io.vertx.junit5.VertxTestContext;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.junit.jupiter.api.extension.ExtendWith;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.SNMPDeviceCatalog.*;
import static com.mindarray.eventbus.EventBusConstants.*;
import static org.apache.http.HttpStatus.SC_OK;
import static org.junit.jupiter.api.Assertions.assertEquals;

@ExtendWith(VertxExtension.class)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
@Timeout(70 * 1000)
@EnabledIfSystemProperty(named = "test.mode", matches = "^APP|^PRIMARY$")
public class TestOtherObjectDiscovery
{
    public static final JsonObject DISCOVERY_PROFILES = new JsonObject();
    public static final Map<Long, VertxTestContext> DISCOVERY_ITEMS = new HashMap<>();
    private static final JsonObject SNMP_DEVICE_CATALOG = new JsonObject()
            .put(SNMP_DEVICE_CATALOG_MODEL, "test").put(SNMP_DEVICE_CATALOG_OID, ".1.3.6.1.4.1.8072.3.2.10").put(SNMP_DEVICE_CATALOG_TYPE, NMSConstants.Type.SYMANTEC_MESSAGING_GATEWAY.getName())
            .put(SNMP_DEVICE_CATALOG_VENDOR, "Vendor").put("_type", "1");
    private static final Logger LOGGER = new Logger(TestOtherObjectDiscovery.class, MOTADATA_API, "Test Other Object Discovery");
    private static MessageConsumer<JsonObject> messageConsumer = null;

    @BeforeAll
    static void beforeAll(VertxTestContext testContext)
    {
        try
        {
            assertDiscoveryConsumerSetup();

            TestUtil.startEventStreaming(new JsonObject().put(EventBusConstants.EVENT_STATE, EventBusConstants.EVENT_STATE_COMPLETED));

            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "src" + GlobalConstants.PATH_SEPARATOR
                    + "test" + GlobalConstants.PATH_SEPARATOR + "resources" + GlobalConstants.PATH_SEPARATOR + "discovery-parameters.json");

            if (file.exists())
            {
                DISCOVERY_PROFILES.mergeIn(new JsonObject(Files.readString(file.toPath(), StandardCharsets.UTF_8)));

                testContext.completeNow();
            }


        }
        catch (Exception exception)
        {
            testContext.failNow(exception.getMessage());

            exception.printStackTrace();
        }
    }

    private static void assertDiscoveryConsumerSetup()
    {
        messageConsumer = TestUtil.vertx().eventBus().localConsumer(EVENT_USER + TestUtil.getSessionId(), message ->
        {
            if (message.body().getBinary(EVENT_CONTEXT) != null && message.body().containsKey(EVENT_COMPRESSION_TYPE) && message.body().getInteger(EVENT_COMPRESSION_TYPE) == COMPRESSION_TYPE_ONE)
            {
                var eventContext = CodecUtil.toJSONObject(message.body().getBinary(EventBusConstants.EVENT_CONTEXT));

                if (eventContext.containsKey(EVENT_NAME) && eventContext.getString(EVENT_NAME).equalsIgnoreCase("discovery"))
                {
                    var context = eventContext.getJsonObject(EVENT_CONTEXT);

                    if (DISCOVERY_ITEMS.containsKey(context.getLong(ID)) && eventContext.getString(EVENT_STATE).equalsIgnoreCase(EVENT_STATE_COMPLETED))
                    {
                        DISCOVERY_ITEMS.get(context.getLong(ID)).verify(() ->
                        {
                            assertEquals(EVENT_STATE_COMPLETED, eventContext.getString(EVENT_STATE));

                            DISCOVERY_ITEMS.get(context.getLong(ID)).completeNow();

                            DISCOVERY_ITEMS.remove(context.getLong(ID));
                        });
                    }
                }
            }
        });
    }

    public static void runOtherDiscoveryTest(VertxTestContext testContext, JsonObject item)
    {
        DISCOVERY_ITEMS.put(item.getLong(ID), testContext);

        TestAPIUtil.post(String.format(TestAPIConstants.DISCOVERY_RUN_API_ENDPOINT, item.getLong(ID)), new JsonObject(), handler -> testContext.verify(() -> assertEquals(SC_OK, handler.result().statusCode())));
    }

    @AfterAll
    static void afterAll(VertxTestContext testContext)
    {
        messageConsumer.unregister(handler -> testContext.completeNow());
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    void testCiscoUCSDiscovery(VertxTestContext testContext, TestInfo testInfo)
    {
        runOtherDiscoveryTest(testContext, DiscoveryConfigStore.getStore().getItemByValue(Discovery.DISCOVERY_NAME, DISCOVERY_PROFILES.getJsonObject(testInfo.getTestMethod().get().getName()).getString(Discovery.DISCOVERY_NAME)));
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(3)
    void testOtherPingDiscoveryWithValidIP(VertxTestContext testContext, TestInfo testInfo)
    {
        runOtherDiscoveryTest(testContext, DiscoveryConfigStore.getStore().getItemByValue(Discovery.DISCOVERY_NAME, DISCOVERY_PROFILES.getJsonObject(testInfo.getTestMethod().get().getName()).getString(Discovery.DISCOVERY_NAME)));
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(3)
    void testSymantecEmailGatewayDiscovery(VertxTestContext testContext, TestInfo testInfo)
    {
        // in our custom db same oid already exist with loadbalancer so sometimes symantec provision randomly failed so firstly remove it from cache and than run discovery
        SNMPDeviceCatalogConfigStore.getStore().flatMap().values().stream().filter(item -> item.getString(SNMP_DEVICE_CATALOG_OID).equalsIgnoreCase(".1.3.6.1.4.1.8072.3.2.10"))
                .map(item -> item.getLong(ID)).forEach(id -> SNMPDeviceCatalogConfigStore.getStore().deleteItem(id));

        TestAPIUtil.post("/api/v1/settings/snmp-device-catalogs", SNMP_DEVICE_CATALOG,
                testContext.succeeding(response ->
                        testContext.verify(() ->
                        {
                            TestAPIUtil.assertCreateEntityTestResult(SNMPDeviceCatalogConfigStore.getStore(), SNMP_DEVICE_CATALOG, response.bodyAsJsonObject(),
                                    String.format(InfoMessageConstants.ENTITY_CREATED, "SNMP Device Catalog"), null, LOGGER, testInfo.getTestMethod().get().getName());

                            runOtherDiscoveryTest(testContext, DiscoveryConfigStore.getStore().getItemByValue(Discovery.DISCOVERY_NAME, DISCOVERY_PROFILES.getJsonObject(testInfo.getTestMethod().get().getName()).getString(Discovery.DISCOVERY_NAME)));
                        })));
    }
}

