package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.LicenseUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;

import java.util.concurrent.atomic.AtomicInteger;

public class LicenseCacheStore extends AbstractCacheStore
{
    private static final LicenseCacheStore STORE = new LicenseCacheStore();

    private static final Logger LOGGER = new Logger(LicenseCacheStore.class, GlobalConstants.MOTADATA_STORE, "License Cache Store");

    private final AtomicInteger consumedLicenseCount = new AtomicInteger(0);
    private final AtomicInteger consumedConfigDeviceLicense = new AtomicInteger(0);

    private final AtomicInteger accessPointLic = new AtomicInteger(0);
    private LicenseCacheStore()
    {
    }

    public static LicenseCacheStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        if (Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.DEFAULT)
        {
            consumedLicenseCount.set(ObjectConfigStore.getStore().getProvisionedItems() +
                    AgentConfigStore.getStore().getProvisionedMetricAgents() +
                    MetricConfigStore.getStore().getProvisionedInstances(NMSConstants.VMS) +
                    MetricConfigStore.getStore().getProvisionedInstances(NMSConstants.APPS));

            accessPointLic.set(MetricConfigStore.getStore().getProvisionedInstances(NMSConstants.ACCESS_POINTS));

            consumedConfigDeviceLicense.set(ConfigurationConfigStore.getStore().getProvisionedItems());

            promise.complete();

            LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
        }

        else
        {
            promise.fail(String.format("failed to init store %s, reason: invalid boot sequence...", this.getClass().getSimpleName()));
        }

        return promise.future();
    }

    public long getConsumedLicenses()
    {
        return consumedLicenseCount.get() + CommonUtil.getInteger(Math.round(Math.ceil(CommonUtil.getDouble(accessPointLic.get()) /
                LicenseUtil.InstanceLicense.ACCESS_POINT.getValue())));
    }

    public void update(String type, int number, boolean provision)
    {
        LOGGER.debug(String.format("Before %s of device type %s and number : %s : " + getConsumedLicenses(),provision?"proision":"unprovision", type, number));

        if (provision)
        {
            if (NMSConstants.ACCESS_POINTS.equalsIgnoreCase(type))
            {
                accessPointLic.set(accessPointLic.get() + number);
            }
            else
            {
                consumedLicenseCount.set(consumedLicenseCount.get() + number);
            }
        }
        else
        {
            if (NMSConstants.ACCESS_POINTS.equalsIgnoreCase(type))
            {
                accessPointLic.set(accessPointLic.get() - number);
            }
            else
            {
                consumedLicenseCount.set(consumedLicenseCount.get() - number);
            }
        }

        LOGGER.debug(String.format("Before %s of device type %s and number : %s : " + getConsumedLicenses(),provision?"proision":"unprovision", type, number));
    }

    /**
     * @param type      type of Objects (example: objects, apps, agents)
     * @param provision `true` if added to cache and `false` to remove from cache
     */
    public void update(String type, boolean provision)
    {
        LOGGER.debug(String.format("Before %s of device type %s : " + getConsumedLicenses(),provision?"proision":"unprovision", type));

        if (provision)
        {
            if (NMSConstants.CONFIG_DEVICES.equalsIgnoreCase(type))
            {
                consumedConfigDeviceLicense.getAndIncrement();
            }
            else
            {
                consumedLicenseCount.getAndIncrement();
            }
        }
        else
        {
            if (NMSConstants.CONFIG_DEVICES.equalsIgnoreCase(type))
            {
                consumedConfigDeviceLicense.getAndDecrement();
            }
            else
            {
                consumedLicenseCount.getAndDecrement();
            }
        }

        LOGGER.debug(String.format("After %s of device type %s : " + getConsumedLicenses(),provision?"proision":"unprovision", type));
    }

    public long getConsumedConfigLicenses()
    {
        return consumedConfigDeviceLicense.get();
    }
}

