package com.mindarray;

import com.mindarray.db.CacheDBServiceProvider;
import com.mindarray.db.ConfigDBServiceProvider;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.eventbus.RemoteEventForwarder;
import com.mindarray.eventbus.RemoteEventSubscriber;
import com.mindarray.ha.ConfigHADatastoreManager;
import com.mindarray.ha.ConfigHADatastoreWriter;
import com.mindarray.util.*;
import io.vertx.core.CompositeFuture;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import org.xerial.snappy.Snappy;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;

import static com.mindarray.Bootstrap.startEngine;
import static com.mindarray.Bootstrap.stop;
import static com.mindarray.GlobalConstants.INSTALLATION_DATE;

public class BootstrapReplica
{
    private static final Logger LOGGER = new Logger(BootstrapReplica.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Replica");

    public void start()
    {
        try
        {

            DBConstants.loadDBConfigs();

            Bootstrap.logSystemConfig();

            MotadataConfigUtil.loadConfigs(new JsonObject(Files.readString(new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + "motadata.json").toPath(), StandardCharsets.UTF_8)));

            ProcessUtil.setProcessors();

            var futures = new ArrayList<Future>();

            var forwarderPort = CommonUtil.getEventSubscriberPort();

            for (var index = 0; index < MotadataConfigUtil.getEventPublishers(); index++)
            {
                var promise = Promise.promise();

                futures.add(promise.future());

                Bootstrap.startEngine(new RemoteEventForwarder(forwarderPort + index), RemoteEventForwarder.class.getSimpleName() + " " + (forwarderPort + index), null).onComplete(handler ->
                {
                    if (handler.succeeded())
                    {
                        promise.complete();
                    }
                    else
                    {
                        promise.fail(handler.cause());
                    }
                });
            }

            CompositeFuture.join(futures).onComplete(asyncResult ->
            {
                if (asyncResult.succeeded())
                {
                    var asyncResults = new ArrayList<Future>();

                    var subscriberPort = CommonUtil.getEventPublisherPort();

                    for (var index = 0; index < MotadataConfigUtil.getEventSubscribers(); index++)
                    {
                        var promise = Promise.promise();

                        asyncResults.add(promise.future());

                        Bootstrap.startEngine(new RemoteEventSubscriber(subscriberPort + index,CommonUtil.getRemoteEventPublisher()), RemoteEventSubscriber.class.getSimpleName() + " " + (subscriberPort + index), null).onComplete(voidAsyncResult ->
                        {
                            if (voidAsyncResult.succeeded())
                            {
                                promise.complete();
                            }
                            else
                            {
                                promise.fail(voidAsyncResult.cause());
                            }
                        });
                    }

                    CompositeFuture.join(asyncResults).onComplete(handler ->
                    {
                        startEngine(new ConfigDBServiceProvider(), ConfigDBServiceProvider.class.getSimpleName(), null)
                                .compose(future -> startEngine(new CacheDBServiceProvider(), CacheDBServiceProvider.class.getSimpleName(), null))
                                .compose(future -> startEngine(new ConfigHADatastoreManager(EventBusConstants.EVENT_DATASTORE_WRITE + "." + DBConstants.DatastoreCategory.CONFIG.getName(), MotadataConfigUtil.getConfigDatastoreWriterInstances(), ConfigHADatastoreWriter.class.getCanonicalName(),true), ConfigHADatastoreManager.class.getCanonicalName(), null))
                               // .compose(future -> startEngine(new HAManager(), HAManager.class.getSimpleName(), null))
                                        .onComplete(result ->
                                        {
                                            try
                                            {
                                                if (result.succeeded())
                                                {
                                                    Bootstrap.configDBService().getOne(DBConstants.COLLECTION_SYSTEM,
                                                            response ->
                                                            {
                                                                if (response.succeeded())
                                                                {
                                                                    LicenseUtil.init(!response.result().containsKey(INSTALLATION_DATE)).onComplete(asyncResponse ->
                                                                    {
                                                                        if (asyncResponse.succeeded())
                                                                        {
                                                                            LOGGER.info("license verified successfully...");

                                                                            try
                                                                            {
                                                                                var license = new JsonObject();

                                                                                if (!Bootstrap.vertx().fileSystem().existsBlocking(LicenseUtil.LICENSE_PATH))
                                                                                {
                                                                                    Bootstrap.vertx().fileSystem().createFileBlocking(LicenseUtil.LICENSE_PATH);

                                                                                    license.mergeIn(asyncResponse.result());

                                                                                    Bootstrap.vertx().fileSystem().writeFileBlocking(LicenseUtil.LICENSE_PATH, Buffer.buffer(CodecUtil.compress(license.encode())));
                                                                                }
                                                                                else
                                                                                {
                                                                                    var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(LicenseUtil.LICENSE_PATH);

                                                                                    license.mergeIn(new JsonObject(new String(Snappy.uncompress(buffer.getBytes()))));

                                                                                    license.mergeIn(asyncResponse.result());

                                                                                }

                                                                                LicenseUtil.load(license);

                                                                                EventBusConstants.setRemoteEventProcessorRegistrationId();

                                                                                EventBusConstants.register(new CipherUtil(), Bootstrap.bootstrapType(), MotadataConfigUtil.getInstallationMode());

                                                                                LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, GlobalConstants.InstallationMode.REPLICA));
                                                                            }
                                                                            catch (Exception exception)
                                                                            {
                                                                                stop(exception);
                                                                            }
                                                                        }
                                                                        else
                                                                        {
                                                                            stop(asyncResponse.cause());
                                                                        }
                                                                    });

                                                                }
                                                                else
                                                                {
                                                                    LOGGER.fatal("something went wrong with config db service..");

                                                                    LOGGER.info("stopping config db service...");
                                                                }
                                                            });
                                                }
                                                else
                                                {
                                                    LOGGER.error(result.cause());
                                                }
                                            }
                                            catch (Exception exception)
                                            {
                                                LOGGER.error(exception);
                                            }
                                        });
                    });

                }
                else
                {
                    LOGGER.error(asyncResult.cause());

                    System.exit(0);
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

