package com.mindarray.store;

import com.mindarray.GlobalConstants;
import com.mindarray.api.Integration;
import com.mindarray.db.DBConstants;
import com.mindarray.runbook.IntegrationEngine;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.json.JsonArray;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class IntegrationConfigStore extends AbstractConfigStore
{

    private static final Logger LOGGER = new Logger(IntegrationConfigStore.class, GlobalConstants.MOTADATA_STORE, "Integration Config Store");

    private static final IntegrationConfigStore STORE = new IntegrationConfigStore();

    private final Map<String, String> tokens = new ConcurrentHashMap<>();

    private IntegrationConfigStore()
    {

        super(DBConstants.COLLECTION_INTEGRATION, LOGGER, false);
    }

    public static IntegrationConfigStore getStore()
    {
        return STORE;
    }

    public String getToken(String integrationType)
    {
        return tokens.getOrDefault(integrationType, GlobalConstants.EMPTY_VALUE);
    }

    public void setToken(String integrationType, String token)
    {
        tokens.put(integrationType, token);
    }

    //returns list of Active Integrations
    public JsonArray getActiveIntegrations()
    {
        var items = new JsonArray();

        for (var entry : this.items.entrySet())
        {
            var item = entry.getValue();

            if (item.containsKey(IntegrationEngine.INTEGRATION_ACCESS_TOKEN))
            {
                items.add(item.getString(Integration.INTEGRATION_TYPE));
            }
        }

        return items;
    }

    @Override
    public Future<Void> updateItem(long id)
    {
        return super.updateItem(id).onComplete(result ->
        {
            if (result.succeeded())
            {
                var item = items.get(id);

                tokens.put(item.getString(Integration.INTEGRATION_TYPE), item.getString(IntegrationEngine.INTEGRATION_ACCESS_TOKEN));
            }
        });
    }

    @Override
    public Future<Void> initStore()
    {
        return super.initStore().onComplete(result ->
        {
            if (result.succeeded())
            {
                for (var entry : items.entrySet())
                {
                    var item = entry.getValue();

                    tokens.put(item.getString(Integration.INTEGRATION_TYPE), item.getString(IntegrationEngine.INTEGRATION_ACCESS_TOKEN));
                }
            }
        });
    }
}

