package com.mindarray.policy;

import com.mindarray.GlobalConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.api.APIConstants;
import com.mindarray.api.MetricPolicy;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.MetricPolicyConfigStore;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.util.*;
import com.mindarray.visualization.VisualizationConstants;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.ENTITY_ID;
import static com.mindarray.eventbus.EventBusConstants.CHANGE_NOTIFICATION_TYPE;
import static com.mindarray.eventbus.EventBusConstants.EVENT_TIMESTAMP;
import static com.mindarray.nms.NMSConstants.CACHE_NAME;
import static com.mindarray.nms.NMSConstants.PREVIOUS_FLAP_TIMESTAMP;

public class MetricPolicyTriggerDurationCalculator extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(MetricPolicyTriggerDurationCalculator.class, GlobalConstants.MOTADATA_POLICY, "Metric Policy Trigger Duration Calculator");

    private final JsonObject objectPolicyStatuses = new JsonObject();

    private final JsonObject policyTriggerTicks = new JsonObject();

    private static final int POLICY_FLAP_DUMP_TIMER_SECONDS = MotadataConfigUtil.getPolicyFlapDumpTimerSeconds();

    private boolean updated = false;
    private AtomicBoolean dirty = new AtomicBoolean();

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            var refreshTimer = new AtomicInteger(POLICY_FLAP_DUMP_TIMER_SECONDS);

            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.METRIC_POLICY_TRIGGER_TICKS);

            if (file.exists())
            {
                var buffer = vertx.fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    policyTriggerTicks.mergeIn(new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))));

                    LOGGER.info(String.format("%s loaded from the backup file...", PolicyEngineConstants.METRIC_POLICY_TRIGGER_TICKS));
                }
            }
            else
            {
                vertx.fileSystem().createFileBlocking(file.getPath());
            }

            file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.METRIC_POLICY_FLAP_DURATIONS);

            if (file.exists())
                {
                    var buffer = vertx.fileSystem().readFileBlocking(file.getPath());

                    if (buffer != null && buffer.getBytes().length > 0)
                    {
                        new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).getMap().forEach((key,value) -> objectPolicyStatuses.put(key,JsonObject.mapFrom(value)));

                        LOGGER.info(String.format("%s loaded from the backup file...", PolicyEngineConstants.METRIC_POLICY_FLAP_DURATIONS));
                    }
                }
                else
                {
                    vertx.fileSystem().createFileBlocking(file.getPath());
                }

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_POLICY_SEVERITY_DURATION_CALCULATE, message ->
            {
                try
                {

                    if (!message.body().isEmpty())
                    {
                        var event = message.body();

                        var key = event.getLong(ENTITY_ID) + SEPARATOR + event.getLong(ID) + SEPARATOR + (event.getValue(INSTANCE, null) != null && !CommonUtil.getString(event.getValue(INSTANCE)).isEmpty() ? event.getString(GlobalConstants.METRIC) + SEPARATOR + event.getValue(INSTANCE) : event.getString(GlobalConstants.METRIC));

                        var flap = send(event, key);

                        if (objectPolicyStatuses.containsKey(key))
                            {
                                if (flap)//now there is flap need to change flap timestamp
                                {
                                    objectPolicyStatuses.getJsonObject(key).mergeIn(event).put(PolicyEngineConstants.POLICY_NOTE,EMPTY_VALUE).put(PREVIOUS_FLAP_TIMESTAMP,event.getLong(EVENT_TIMESTAMP)).remove(PolicyEngineConstants.POLICY_ACKNOWLEDGE);
                                }
                                else
                                {
                                    objectPolicyStatuses.getJsonObject(key).mergeIn(event);
                                }
                            }
                            else
                            {
                                objectPolicyStatuses.put(key,event.put(DURATION,0).put(PolicyEngineConstants.POLICY_NOTE,EMPTY_VALUE).put(PREVIOUS_FLAP_TIMESTAMP,event.getLong(EVENT_TIMESTAMP)));
                            }

                        if (!policyTriggerTicks.containsKey(key))
                        {
                            updated = true;

                            policyTriggerTicks.put(key, System.currentTimeMillis());
                        }

                        event.put(PolicyEngineConstants.POLICY_FIRST_TRIGGER_TICK, policyTriggerTicks.getLong(key));
                    }
                }

                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CHANGE_NOTIFICATION
                    , message ->
                    {
                        var event = message.body();

                        if (EventBusConstants.ChangeNotificationType.valueOf(event.getString(EventBusConstants.CHANGE_NOTIFICATION_TYPE)) == EventBusConstants.ChangeNotificationType.CACHE_SYNC)
                        {
                            if (dirty.get())
                            {
                                dirty.set(false);

                                vertx.eventBus().send(EventBusConstants.ChangeNotificationType.CACHE_SYNC.name() + ".reply",new JsonObject().put(CACHE_NAME,PolicyEngineConstants.METRIC_POLICY_TRIGGER_TICKS).put(STATUS,STATUS_SUCCEED).put(RESULT,vertx.fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.METRIC_POLICY_TRIGGER_TICKS)));
                            }

                            if (!objectPolicyStatuses.isEmpty())
                            {
                                vertx.eventBus().send(EventBusConstants.ChangeNotificationType.CACHE_SYNC.name() + ".reply",new JsonObject().put(CACHE_NAME,PolicyEngineConstants.METRIC_POLICY_FLAP_DURATIONS).put(STATUS,STATUS_SUCCEED).put(RESULT,vertx.fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.METRIC_POLICY_FLAP_DURATIONS)));
                            }
                        }

                    }).exceptionHandler(LOGGER::error);

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_METRIC_POLICY_TRIGGER_DURATION_QUERY, message -> message.reply(new JsonObject().mergeIn(objectPolicyStatuses)));

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.METRIC_POLICY_TRIGGER_TICK_QUERY, message -> message.reply(new JsonObject().mergeIn(policyTriggerTicks)));

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.METRIC_POLICY_ACKNOWLEDGE, message ->
                {
                    var event = message.body();

                    var policy = MetricPolicyConfigStore.getStore().getItem(event.getLong(PolicyEngineConstants.POLICY_ID));

                    var key = event.getLong(AIOpsObject.OBJECT_ID) + SEPARATOR + event.getLong(PolicyEngineConstants.POLICY_ID) + SEPARATOR + (event.getValue(INSTANCE, null) != null && !CommonUtil.getString(event.getValue(INSTANCE)).isEmpty() ? policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC) + SEPARATOR + event.getValue(INSTANCE) : policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC));

                    var data = new JsonObject().mergeIn(event).put(PolicyEngineConstants.POLICY_ACKNOWLEDGE_TIME, DateTimeUtil.currentMilliSeconds());

                    data.remove(AIOpsObject.OBJECT_ID);

                    data.remove(PolicyEngineConstants.POLICY_ID);

                    data.remove(INSTANCE);

                    if (data.getInteger("acknowledge") == 1)
                    {
                        objectPolicyStatuses.getJsonObject(key).put(PolicyEngineConstants.POLICY_ACKNOWLEDGE,data.encode());
                    }
                    else
                    {
                        objectPolicyStatuses.getJsonObject(key).remove(PolicyEngineConstants.POLICY_ACKNOWLEDGE);
                    }
                });

                vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.METRIC_POLICY_NOTE, message ->
                {
                    var event = message.body();

                    var policy = MetricPolicyConfigStore.getStore().getItem(event.getLong(PolicyEngineConstants.POLICY_ID));

                    var key = event.getLong(AIOpsObject.OBJECT_ID) + SEPARATOR + event.getLong(PolicyEngineConstants.POLICY_ID) + SEPARATOR + (event.getValue(INSTANCE, null) != null && !CommonUtil.getString(event.getValue(INSTANCE)).isEmpty() ? policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC) + SEPARATOR + event.getValue(INSTANCE) : policy.getJsonObject(PolicyEngineConstants.POLICY_CONTEXT).getString(METRIC));

                    objectPolicyStatuses.getJsonObject(key).put(PolicyEngineConstants.POLICY_NOTE,event.getString(PolicyEngineConstants.POLICY_NOTE));
                });vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CHANGE_NOTIFICATION, message ->
            {
                var event = message.body();

                if (EventBusConstants.ChangeNotificationType.valueOf(event.getString(CHANGE_NOTIFICATION_TYPE)) == EventBusConstants.ChangeNotificationType.DELETE_OBJECT)
                {
                    objectPolicyStatuses.getMap().keySet().removeIf(key -> CommonUtil.getLong(key.split(SEPARATOR_WITH_ESCAPE)[0].trim()) == event.getLong(ID));
                }
            }).exceptionHandler(LOGGER::error);

            vertx.setPeriodic(10 * 1000L, timer -> write());

                vertx.setPeriodic(30 * 1000L, timer ->
                {
                    if (updated)
                    {
                        dirty.set(true);

                        updated = false;

                        vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.METRIC_POLICY_TRIGGER_TICKS,
                                Buffer.buffer(CodecUtil.compress(policyTriggerTicks.encode().getBytes())));
                    }

                    refreshTimer.set(refreshTimer.get() - 30);

                    if (refreshTimer.get() <= 0){

                        vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.METRIC_POLICY_FLAP_DURATIONS,
                                Buffer.buffer(CodecUtil.compress(new JsonObject().mergeIn(objectPolicyStatuses).encode().getBytes())));

                        refreshTimer.set(POLICY_FLAP_DUMP_TIMER_SECONDS);
                    }
                });
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }

    private void write()
    {
        var deletedEntries = new HashSet<String>();

        objectPolicyStatuses.getMap().forEach((key, values) ->
        {
            try
            {
                var value = (JsonObject)values;

                var objectId = value.getLong(APIConstants.ENTITY_ID);

                var object = ObjectConfigStore.getStore().getItem(objectId, false);

                if (object != null)
                {
                    value.put(DURATION, value.getInteger(DURATION, 0) + 10);
                }
                else
                {
                    // just for safer purpose will be keeping check if object null and its keys not removed so will be removing keys forcefully
                    deletedEntries.add(key);
                }

                if (!deletedEntries.isEmpty())
                {
                    deletedEntries.forEach(objectPolicyStatuses::remove);
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        promise.complete();
    }

    private boolean send(JsonObject context, String key)
    {
        var flap = false;

        if (objectPolicyStatuses.containsKey(key) && !objectPolicyStatuses.getJsonObject(key).getString(SEVERITY).equalsIgnoreCase(context.getString(SEVERITY)))
        {
            send(objectPolicyStatuses.getJsonObject(key));//if flap then send data to DB..

            flap =true;
        }

        return flap;
    }

    private void send(JsonObject value)
    {
        try
        {
            var buffer = Buffer.buffer();

            appendBytes(buffer,value.getLong(PREVIOUS_FLAP_TIMESTAMP),DBConstants.PluginId.POLICY_DURATION_METRIC.getName());

            updateEventFieldsBatch(AIOpsObject.OBJECT_ID,CommonUtil.getString(ObjectConfigStore.getStore().getItem(value.getLong(APIConstants.ENTITY_ID), false).getInteger(AIOpsObject.OBJECT_ID)), buffer);

            updateEventFieldsBatch(INSTANCE,value.containsKey(INSTANCE) && !value.getString(INSTANCE).isEmpty() ? CommonUtil.getString(value.getValue(INSTANCE)) : EMPTY_VALUE, buffer);

            updateEventFieldsBatch(PolicyEngineConstants.POLICY_ID,CommonUtil.getString(value.getLong(ID)), buffer);

            updateEventFieldsBatch(DURATION,CommonUtil.getString(value.getInteger(DURATION)),buffer);

            updateEventFieldsBatch(SEVERITY,value.getString(SEVERITY),buffer);

            updateEventFieldsBatch(MetricPolicy.POLICY_THRESHOLD,CommonUtil.getString(value.getValue(MetricPolicy.POLICY_THRESHOLD,EMPTY_VALUE)),buffer);

            updateEventFieldsBatch(VALUE,CommonUtil.getString(value.getValue(VALUE)),buffer);

            updateEventFieldsBatch(METRIC,CommonUtil.getString(value.getValue(METRIC)),buffer);

            updateEventFieldsBatch(PolicyEngineConstants.POLICY_TYPE,CommonUtil.getString(value.getValue(PolicyEngineConstants.POLICY_TYPE)),buffer);

            vertx.eventBus().send(EventBusConstants.EVENT_DATASTORE_WRITE + "." + DBConstants.DatastoreCategory.EVENT.getName(), buffer.getBytes());

            value.put(DURATION,0);

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void appendBytes(Buffer bytes, long timestamp, int pluginId)
    {
        bytes.setLongLE(0, timestamp);

        var plugin = pluginId + DASH_SEPARATOR + VisualizationConstants.VisualizationDataSource.POLICY_FLAP.getName().toLowerCase();

        bytes.appendIntLE(plugin.length());

        bytes.appendString(plugin);

        bytes.appendByte(DBConstants.DatastoreFormat.HORIZONTAL.getName().byteValue());

        bytes.appendByte(CommonUtil.getByteValue(DBConstants.DatastoreType.POLICY_FLAP_HISTORY.ordinal()));

        bytes.appendShortLE(CommonUtil.getShort(EMPTY_VALUE.length()));

        bytes.appendString(EMPTY_VALUE);
    }

    private void updateEventFieldsBatch(String column, String value,Buffer buffer)
    {
        try
        {
            var category = DBConstants.DataCategory.STRING.getName();

            if (column.equalsIgnoreCase(PolicyEngineConstants.POLICY_ID) || column.equalsIgnoreCase(DURATION) || column.equalsIgnoreCase(AIOpsObject.OBJECT_ID))
            {
                category = DBConstants.DataCategory.NUMERIC.getName();
            }

            buffer.appendByte(category);

            buffer.appendIntLE(column.length());

            buffer.appendString(column);

            if (category == DBConstants.DataCategory.NUMERIC.getName())//if it has decimal number than convert it into integer
            {
                buffer.appendLongLE(Math.round(CommonUtil.getDouble(value)));
            }
            else
            {
                var fieldValue = value.getBytes(StandardCharsets.UTF_8);

                buffer.appendIntLE(fieldValue.length);

                buffer.appendBytes(fieldValue);
            }
        }
