    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router);

            router.get("/" + endpoint + "/:id/references").handler(this::getReferences);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    protected Future<JsonObject> getEntityCountPreHook(JsonObject response)
    {
        try
        {
            var ids = BusinessHourConfigStore.getStore().getIds();

            for (var index = 0; index < ids.size(); index++)
            {
                var id = ids.getLong(index);

                var count = response.getInteger(CommonUtil.getString(id), 0);

                count += CorrectionProfileConfigStore.getStore().getItemsByMapValueField(CorrectionProfile.CORRECTION_PROFILE_CONTEXT, CorrectionProfile.BUSINESS_HOUR_PROFILE, id).size();

                response.put(CommonUtil.getString(id), count);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture(response);
    }


