```
package com.mindarray.ha;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.APIConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.api.User;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.*;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.MappedByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.db.DBConstants.DB_QUERY;
import static com.mindarray.eventbus.EventBusConstants.*;

public class ConfigManager extends AbstractVerticle {
    private static final Logger LOGGER = new Logger(ConfigManager.class, GlobalConstants.MOTADATA_DB, "Config DB Manager");
    private String path;
    private byte[] bytes = new byte[8 * 1024];
    private final long maxBufferLength = MotadataConfigUtil.getDatastoreWriterMaxBufferMB() * (1048576);
    private final Map<String, Long> itemsByUUID = new HashMap<>(); //items by uuid store last read file
    private final Map<Long, FileChannel> eventFileReaderChannels = new TreeMap<>(); //store all files by time order (milliseconds)
    private final Map<Long, MappedByteBuffer> eventFileMappedByteBuffers = new TreeMap<>(); //store all files by time order (milliseconds)

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            if(Bootstrap.bootstrapType().name().equalsIgnoreCase(BootstrapType.OBSERVER.name()))
            {
                var storeDir = new File(CURRENT_DIR + PATH_SEPARATOR + EventBusConstants.EVENT_DIR + PATH_SEPARATOR
                        + EventBusConstants.replace(EventBusConstants.EVENT_DATASTORE_WRITE
                        + GlobalConstants.DOT_SEPARATOR + DBConstants.DatastoreCategory.CONFIG.getName()));

                path = storeDir.getPath();

                if (!storeDir.exists())
                {
                    storeDir.mkdirs();
                }

                load(storeDir);

                vertx.setPeriodic(120 * 1000, handler -> purge());

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_SYNC_WRITE, event -> write(event.body())).exceptionHandler(LOGGER::error);

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_SYNC_READ, event -> read(event.body())).exceptionHandler(LOGGER::error);
            }
            else if(Bootstrap.bootstrapType().name().equalsIgnoreCase(BootstrapType.APP.name()))
            {
                if(MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.PRIMARY.name()))
                {
                    vertx.setPeriodic(MotadataConfigUtil.getConfigDBRequestTimer(), handler ->
                    {
                        if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
                        {
                            vertx.eventBus().send(EVENT_HA_OBSERVER,
                                    new JsonObject().put(EVENT_TYPE,EVENT_CONFIG_SYNC_READ)
                                            .put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                            .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,Bootstrap.getRegistrationId())
                                            .put(DatastoreConstants.DATASTORE_WRITER_MAX_BUFFER_BYTES,1048576L));
                        }

                        if(Bootstrap.isSynced())
                        {
                            vertx.cancelTimer(handler);
                        }
                    });

                    vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_SYNC_FLUSH, message -> decodeEvent(message.body()));
                }
                else
                {
                    vertx.setPeriodic(MotadataConfigUtil.getConfigDBRequestTimer(), handler ->
                    {
                        if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
                        {
                            vertx.eventBus().send(EVENT_HA_OBSERVER,
                                    new JsonObject().put(EVENT_TYPE,EVENT_CONFIG_SYNC_READ)
                                            .put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                            .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,Bootstrap.getRegistrationId())
                                            .put(DatastoreConstants.DATASTORE_WRITER_MAX_BUFFER_BYTES,1048576L));
                        }
                    });

                    vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_SYNC_FLUSH, message -> decodeEvent(message.body()));
                }
            }

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void load(File storeDirectory)
    {
        try
        {
            var files = new File(storeDirectory.getPath()).listFiles();

            if (files != null)
            {
                for (var file : files)
                {
                    if (file.getName().equalsIgnoreCase("bookmarks"))
                    {
                        var timestamp = CommonUtil.getLong(file.getName().trim());

                        var eventFile = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp);

                        eventFileReaderChannels.put(timestamp,FileChannel.open(eventFile.toPath(), StandardOpenOption.READ));

                        eventFileMappedByteBuffers.put(timestamp,eventFileReaderChannels.get(timestamp).map(FileChannel.MapMode.READ_ONLY, 0, eventFile.length()));
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void write(JsonObject context)
    {
        try
        {
            decodeEvent(context);

            var buffer = context.getBinary(EVENT_CONTEXT);

            var timestamp = context.getLong(EVENT_TIMESTAMP);

            BufferedOutputStream bufferedOutputStream;

            try (var fileOutputStream = new FileOutputStream(path + GlobalConstants.PATH_SEPARATOR + timestamp, false))
            {
                bufferedOutputStream = new BufferedOutputStream(fileOutputStream, this.bytes.length);

                bufferedOutputStream.write(buffer, 0, buffer.length);

                bufferedOutputStream.flush();

                bufferedOutputStream.close();

                var eventFile = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp);

                eventFileReaderChannels.put(timestamp,FileChannel.open(eventFile.toPath(), StandardOpenOption.READ));

                eventFileMappedByteBuffers.put(timestamp,eventFileReaderChannels.get(timestamp).map(FileChannel.MapMode.READ_ONLY, 0, eventFile.length()));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void read(JsonObject context)
    {
        try
        {
            var length = 0;

            var uuid = context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID);

            var timestamp = itemsByUUID.getOrDefault(uuid,0L);

            for (Map.Entry<Long, FileChannel> entry : eventFileReaderChannels.entrySet())
            {
                if (entry.getKey() > timestamp && length <= maxBufferLength)
                {
                    var eventFile = new File(path + GlobalConstants.PATH_SEPARATOR + entry.getKey());

                    var bufferBytes = new byte[CommonUtil.getInteger(eventFile.length())];

                    eventFileMappedByteBuffers.get(entry.getKey()).get(0, bufferBytes, 0, bufferBytes.length);

                    vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER, new JsonObject().put(EVENT_CONTEXT, bufferBytes)
                            .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC)
                            .put(EVENT_COPY_REQUIRED, false).put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, uuid)
                            .put(EVENT_TYPE, EventBusConstants.EVENT_CONFIG_SYNC_FLUSH));

                    itemsByUUID.put(uuid, entry.getKey());

                    length = length + bufferBytes.length;
                }
            }

            if(length == 0 && context.getString(INSTALLATION_MODE).equalsIgnoreCase(InstallationMode.PRIMARY.name()))
            {
                vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER,new JsonObject().put(EVENT_CONTEXT,new byte[0])
                        .put(EVENT_TOPIC,REMOTE_EVENT_PROCESSOR_TOPIC)
                        .put(EVENT_COPY_REQUIRED,false).put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,uuid)
                        .put(EVENT_TYPE, EventBusConstants.EVENT_CONFIG_SYNC_ACKNOWLEDGEMENT));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void decodeEvent(JsonObject event)
    {
        var offset = 0;

        var byteBuffer = Buffer.buffer(event.getBinary(EVENT_CONTEXT));

        while(offset < byteBuffer.length())
        {
            try
            {
                var rowLength = byteBuffer.getIntLE(offset); // read row length

                if(rowLength > 0)
                {
                    offset = offset + 4; //skip row length bytes

                    var bytes = Buffer.buffer(CodecUtil.toBytes(byteBuffer.getBytes(offset, offset + rowLength))); // read row bytes snappy compressed

                    System.out.println(new JsonObject(new String(bytes.getBytes(12,12 + bytes.getIntLE(8)))).encode());

                    updateConfig(new JsonObject(new String(bytes.getBytes(12,12 + bytes.getIntLE(8))))); // decode row bytes

                    offset = offset + rowLength; //skip row buffer length bytes
                }
                else
                {
                    LOGGER.warn(String.format("ignore batch decode in db metric store file %s = %s / %s / %s = ", event.getString(EVENT_FILE),offset,rowLength,byteBuffer.length()));

                    break;
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }
    }

    private void updateConfig(JsonObject context)
    {
        try
        {
            if(context.containsKey(DBConstants.HA_OPERATION))
            {
                var collection = context.getString(APIConstants.ENTITY_COLLECTION);

                var type = DBConstants.HAOperation.valueOfName(CommonUtil.getByteValue(context.getValue(DBConstants.HA_OPERATION)));

                if(collection != null)
                {
                    LOGGER.trace(String.format("performing operation %s on collection %s",type,collection));
                }

                switch (type)
                {
                    case SAVE ->
                    {
                        if(!context.containsKey(EventBusConstants.EVENT_ROUTER_CONFIG))
                        {
                            Bootstrap.configDBService().save(collection, context.getJsonArray(DBConstants.DB_DOCUMENTS).getJsonObject(0), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                                    false, handler ->
                                    {
                                        if (handler.succeeded())
                                        {
                                            LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                        }
                                        else
                                        {
                                            LOGGER.error(handler.cause());

                                            LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                        }
                                    });
                        }
                        else
                        {
                            var cacheFile = context.getString(NMSConstants.CACHE_NAME);

                            if (CommonUtil.isNotNullOrEmpty(cacheFile) && context.getBinary(GlobalConstants.RESULT) != null && context.getBinary(RESULT).length > 0)
                            {
                                LOGGER.info(String.format("received updated cache file %s ",cacheFile));

                                Bootstrap.vertx().fileSystem().writeFileBlocking(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + cacheFile,
                                        Buffer.buffer(context.getBinary(RESULT)));
                            }                        }
                    }

                    case SAVE_ALL -> Bootstrap.configDBService().saveAll(collection, context.getJsonArray(DBConstants.DB_DOCUMENTS), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            false, handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));

                                }
                            });

                    case UPDATE -> Bootstrap.configDBService().update(collection, context.getJsonObject(DBConstants.DB_QUERY), context.getJsonArray(DBConstants.DB_DOCUMENTS).getJsonObject(0), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            false, handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());
                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));

                                }
                            });

                    case UPDATE_ALL -> Bootstrap.configDBService().updateAll(collection, context.getJsonObject(DBConstants.DB_QUERY), context.getJsonObject(DBConstants.DB_DOCUMENTS), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            false, handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                }
                            });

                    case UPSERT -> Bootstrap.configDBService().upsert(collection,context.getJsonObject(DB_QUERY),context.getJsonArray(DBConstants.DB_DOCUMENTS).getJsonObject(0),SYSTEM_USER,SYSTEM_REMOTE_ADDRESS,false,result ->
                    {
                        if (result.succeeded())
                        {
                            LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                        }
                        else
                        {
                            LOGGER.error(result.cause());

                            LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                        }
                    });

                    case DELETE -> Bootstrap.configDBService().delete(collection, context.getJsonObject(DBConstants.DB_QUERY), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            false, handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                }
                            });

                    case DELETE_ALL -> Bootstrap.configDBService().deleteAll(collection, context.getJsonObject(DBConstants.DB_QUERY), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            false, handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                }
                            });

                    case DROP -> Bootstrap.configDBService().drop(collection,
                            false, handler ->
                            {
                                if (handler.failed())
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                }
                            });

                    default -> { }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void saveBookmarks()
    {
        try
        {
            var bookmarks = new JsonObject();

            if(!itemsByUUID.isEmpty())
            {
                itemsByUUID.forEach((key, value) -> bookmarks.put(CommonUtil.getString(key), CommonUtil.getString(value))); // offset+event queue size

                Bootstrap.vertx().fileSystem().writeFileBlocking(path + GlobalConstants.PATH_SEPARATOR + "bookmarks", bookmarks.toBuffer());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void purge()
    {
        try
        {
            if(!itemsByUUID.isEmpty())
            {
                var value = CommonUtil.getLong(Collections.min(itemsByUUID.values()));

                for (var iterator = eventFileReaderChannels.entrySet().iterator(); iterator.hasNext(); )
                {
                    var entry = iterator.next();

                    if( entry.getKey() <= value)
                    {
                        entry.getValue().close();

                        iterator.remove();

                        Files.deleteIfExists(Paths.get(path + GlobalConstants.PATH_SEPARATOR + entry.getKey()));

                        eventFileMappedByteBuffers.remove(entry.getKey());
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        promise.complete();
    }
