import java.util.function.Consumer;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.EVENT_TOPIC;

/**
 * TCPClient is a Vert.x-based TCP transport client implementation
 * that connects to a remote TCP server, sends/receives data, and
 * integrates with the Vert.x EventBus for message dispatch.
 */
public class TCPClient implements TransportClient {

    // TCP client configuration (host, port, event type, etc.)
    private final JsonObject config;

    // Event type associated with messages for this client
    private final String eventType;

    // The active TCP socket connection to the server
    private NetSocket socket;

    // Consumer to handle incoming byte[] messages
    private Consumer<byte[]> consumer;

    // Logger for TCP client-specific logging
    private static final Logger LOGGER = new Logger(TCPClient.class, GlobalConstants.MOTADATA_EVENT_BUS, "TCP Client");

    // Remote event topic (parsed from bootstrap type)
    private final String remoteEventTopic = EventBusConstants.getRemoteEventTopic(Bootstrap.bootstrapType()).split(DOT_SEPARATOR_ESCAPE, 2)[1];

    /**
     * Creates a new TCPClient instance with the given configuration.
     *
     * @param config JSON configuration containing host, port, and event type.
     */
    public TCPClient(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EventBusConstants.EVENT_TYPE);

        // Default consumer sends incoming bytes to the Vert.x EventBus under eventType
        consumer = bytes -> Bootstrap.vertx().eventBus().send(eventType, bytes);
    }

    /**
     * Establishes a TCP connection to the configured host and port.
     * Uses Vert.x NetClient with optimized TCP options.
     *
     * @return Future indicating connection success/failure (never fails for APP manager).
     */
    @Override
    public Future<Void> connect()
    {
        var promise = Promise.<Void>promise();

        var clientOptions = new NetClientOptions()
                .setReconnectAttempts(5)
                .setReconnectInterval(MotadataConfigUtil.getEventRemoteReconnectIntervalSeconds(
                        EventBusConstants.TransportProtocol.TCP.getValue()))
                .setReuseAddress(true)
                .setReusePort(true)
                .setTcpFastOpen(true)
                .setTcpNoDelay(true)
                .setTcpKeepAlive(true)
                .setTcpCork(true)
                .setSendBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes())
                .setReceiveBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes());

        if (MotadataConfigUtil.tcpSslEnabled())
        {
            clientOptions.setSsl(true).setTrustAll(false).setHostnameVerificationAlgorithm(EMPTY_VALUE)
                    .setEnabledSecureTransportProtocols(Set.of("TLSv1.2", "TLSv1.3"))
                    .setTrustOptions(new PemTrustOptions().addCertPath(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "server-cert.pem"));
        }

        var client = Bootstrap.vertx().createNetClient(clientOptions);

        // Attempt to connect to the remote TCP server
        client.connect(config.getInteger(PORT), config.getString(HOST))
                .onComplete(handler ->
                {
                    try
                    {
                        if (handler.succeeded())
                        {
                            socket = handler.result();

                            // Send initial registration message with event topic
                            socket.write(Buffer.buffer(new JsonObject()
                                    .put(EVENT_TOPIC, EventBusConstants.getRemoteEventTopic(Bootstrap.bootstrapType()))
                                    .encode()
                                    .getBytes(StandardCharsets.UTF_8)));

                            LOGGER.info(String.format("%s client is successfully connected with port %s", Bootstrap.bootstrapType(), config.getInteger(PORT)));

                            promise.complete();
                        }
                        else
                        {
                            LOGGER.warn(String.format("%s error while connecting :%s ", Bootstrap.bootstrapType(), handler.cause()));

                            // For APP manager: do not fail the promise, if connection fails.otherwise app won't start
                            if (Bootstrap.bootstrapType() == BootstrapType.MANAGER
                                    && MotadataConfigUtil.getSystemBootstrapType().equalsIgnoreCase(BootstrapType.APP.name())
                                    && handler.cause() instanceof ConnectException)
                            {
                                promise.complete();
                            }
                            else
                            {
                                promise.fail(handler.cause());
                            }
                        }
                    }
                    catch (Exception exception)
                    {
                        // Log and fail promise if an unexpected error occurs
                        LOGGER.warn(String.format("error occurred while connecting in %s ", Bootstrap.bootstrapType()));

                        LOGGER.error(exception);

                        promise.fail(exception);
                    }
                });

        return promise.future();
    }

    /**
     * Sends a message (byte[]) over the TCP socket.
     * Appends a value separator at the end for message framing.
     *
     * @param bytes The byte array to send.
     */
    // improvement : implement buffer pooling concept to reuse buffer, if needed in the future.
    @Override
    public void send(byte[] bytes)
    {
        try
        {
            if (socket != null)
            {
                // Write data to the socket followed by a delimiter
                socket.write(Buffer.buffer(bytes).appendString(VALUE_SEPARATOR_WITH_ESCAPE));

                if (CommonUtil.traceEnabled())
                {
                    LOGGER.trace(String.format("%s sending data to address : %s:%s ", Bootstrap.bootstrapType(), config.getString(HOST),config.getInteger(PORT)));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn(String.format("error occurred while sending in %s to address : %s:%s ",Bootstrap.bootstrapType(),config.getString(HOST),config.getInteger(PORT)));

            LOGGER.error(exception);
        }
    }

    /**
     * Sets up a record parser to handle incoming TCP messages.
     * Messages are split using VALUE_SEPARATOR_WITH_ESCAPE as the delimiter.
     *
     * @return A succeeded Future since setup is synchronous.
     */
    @Override
    public Future<Void> receive()
    {
        // Create a parser that splits incoming data based on a delimiter
        RecordParser.newDelimited(VALUE_SEPARATOR_WITH_ESCAPE, socket).handler(buffer ->
        {
            try
            {
                if (buffer != null && buffer.length() > 0)
                {
                    // Build message format: [topic length][topic bytes][payload bytes]
                    consumer.accept(Buffer.buffer()
                            .appendShortLE(CommonUtil.getShort(remoteEventTopic.getBytes().length))
                            .appendBytes(remoteEventTopic.getBytes())
                            .appendBytes(buffer.getBytes())
                            .getBytes());

                    if (CommonUtil.traceEnabled())
                    {
                        LOGGER.trace(String.format("%s received bytes of length : %s at port : %s ", Bootstrap.bootstrapType(), buffer.length(), config.getInteger(PORT)));
                    }
                }
            }
            catch (Exception exception)
            {
                LOGGER.warn(String.format("error occurred in %s ", Bootstrap.bootstrapType()));

                LOGGER.error(exception);
            }
        });

        return Future.succeededFuture();
    }

    /**
     * Registers a custom handler for incoming byte[] messages.
     *
     * @param handler A Consumer that will process incoming messages.
     */
    @Override
    public void registerMessageHandler(Consumer<byte[]> handler) {
        this.consumer = handler;
    }

    /**
     * Closes the TCP connection if open.
     *
     * @return Future that completes when the socket is closed.
     */
    @Override
    public Future<Void> close()
    {
        try
        {
            LOGGER.info(String.format("%s client port : %s event.type : %s is closed ...", Bootstrap.bootstrapType(), config.getInteger(PORT), eventType));

            if (socket != null)
            {
                return socket.close();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture();
    }
}

