    private void removeOldDependencies(JsonObject context, byte level, JsonObject existingItem, JsonObject item)
    {
        // first remove old dependencies
        Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_DEPENDENCY + "." + AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName(),
                context.clear().put(AIOpsConstants.DEPENDENCY_SOURCE, existingItem.getString(DEPENDENCY_MAPPER_PARENT) + VALUE_SEPARATOR + existingItem.getString(DEPENDENCY_MAPPER_PARENT_INTERFACE))
                        .put(AIOpsConstants.DEPENDENCY_LEVEL, level)
                        .put(AIOpsConstants.DEPENDENCY_DEPENDENT_FIELD, CommonUtil.isNotNullOrEmpty(existingItem.getString(DEPENDENCY_MAPPER_CHILD_INTERFACE))
                                ? existingItem.getString(DEPENDENCY_MAPPER_CHILD) + VALUE_SEPARATOR + existingItem.getString(DEPENDENCY_MAPPER_CHILD_INTERFACE) : existingItem.getString(DEPENDENCY_MAPPER_CHILD))
                        .put(AIOpsConstants.DEPENDENCY_TYPE, AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName())
                        .put(AIOpsConstants.DEPENDENCY_OPERATION, AIOpsConstants.DependencyOperation.REMOVE_MULTIPLES.getName()));

        // remove old dependency parent
        Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_DEPENDENCY + "." + AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName(),
                context.clear().put(AIOpsConstants.DEPENDENCY_SOURCE, existingItem.getString(DEPENDENCY_MAPPER_PARENT) + VALUE_SEPARATOR + existingItem.getString(DEPENDENCY_MAPPER_PARENT_INTERFACE))
                        .put(AIOpsConstants.DEPENDENCY_LEVEL, AIOpsConstants.DependencyLevel.MINUS_ONE.getName())
                        .put(AIOpsConstants.DEPENDENCY_DEPENDENT_FIELD, existingItem.getString(DEPENDENCY_MAPPER_PARENT))
                        .put(AIOpsConstants.DEPENDENCY_TYPE, AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName())
                        .put(AIOpsConstants.DEPENDENCY_OPERATION, AIOpsConstants.DependencyOperation.REMOVE_MULTIPLES.getName()));

        // remove old end device dependency with parent
        if (CommonUtil.isNotNullOrEmpty(item.getString(DEPENDENCY_MAPPER_CHILD_INTERFACE)))
        {
            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_DEPENDENCY + "." + AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName(),
                    context.clear().put(AIOpsConstants.DEPENDENCY_SOURCE, existingItem.getString(DEPENDENCY_MAPPER_CHILD) + VALUE_SEPARATOR + existingItem.getString(DEPENDENCY_MAPPER_CHILD_INTERFACE))
                            .put(AIOpsConstants.DEPENDENCY_LEVEL, level)
                            .put(AIOpsConstants.DEPENDENCY_DEPENDENT_FIELD, CommonUtil.isNotNullOrEmpty(existingItem.getString(DEPENDENCY_MAPPER_PARENT_INTERFACE))
                                    ? existingItem.getString(DEPENDENCY_MAPPER_PARENT) + VALUE_SEPARATOR + existingItem.getString(DEPENDENCY_MAPPER_PARENT_INTERFACE) : existingItem.getString(DEPENDENCY_MAPPER_PARENT))
                            .put(AIOpsConstants.DEPENDENCY_TYPE, AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName())
                            .put(AIOpsConstants.DEPENDENCY_OPERATION, AIOpsConstants.DependencyOperation.REMOVE_MULTIPLES.getName()));

            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_DEPENDENCY + "." + AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName(),
                    context
                            .put(AIOpsConstants.DEPENDENCY_DEPENDENT_FIELD, existingItem.getString(DEPENDENCY_MAPPER_PARENT))
                            .put(AIOpsConstants.DEPENDENCY_LEVEL, AIOpsConstants.DependencyLevel.MINUS_ONE.getName()));
        }
    }

    /**
     * Creates dependency mapper entries from request data.
     * <p>
     * This method handles both single dependency mapper creation and bulk creation via CSV files.
     * For CSV files, it parses the file and validates each entry before saving. For single entries,
     * it validates the request body directly.
     * </p>
     *
     * <p>
     * The method performs the following operations:
     * <ul>
     *   <li>Validates each record against business rules</li>
     *   <li>Saves valid records to the database</li>
     *   <li>Updates the config store with new entries</li>
     *   <li>Sends notifications for each created dependency mapper</li>
     *   <li>Returns appropriate success or error responses</li>
     * </ul>
     * </p>
     *
     * @param routingContext the Vert.x routing context containing the request data
     */
    @Override
    protected void create(RoutingContext routingContext)
    {
        try
        {
            var requestBody = routingContext.body().asJsonObject().put(DEPENDENCY_MAPPER_ARCHIVED, NO);

            var schema = CommonUtil.getEntitySchema(endpoint);

            if (schema != null)
            {
                var table = schema.getString(APIConstants.ENTITY_TABLE);

                var records = new JsonArray();

                if (requestBody.containsKey(DEPENDENCY_MAPPER_FILE))
                {
                    var message = parse(requestBody, records);

                    if (!message.equalsIgnoreCase(EMPTY_VALUE))
                    {
                        this.send(routingContext, new JsonObject().put(APIConstants.RESPONSE_CODE, SC_BAD_REQUEST).put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                .put(GlobalConstants.MESSAGE, String.format("%s : %s", ErrorMessageConstants.DEPENDENCY_MAPPER_FAILED, message)));

                        return;
                    }
                }
                else
                {
                    records.add(requestBody.put(DBConstants.FIELD_TYPE, DBConstants.ENTITY_TYPE_USER));
                }

                if (records.isEmpty())
                {
                    routingContext.response().setStatusCode(HttpStatus.SC_OK).end(new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                            .put(GlobalConstants.MESSAGE, "No entries created").put(ID, new JsonArray()).encode());

                    return;
                }

                // Validate each record before saving
                var message = EMPTY_VALUE;

                for (var index = records.size() - 1; index >= 0; index--)
                {
                    var record = records.getJsonObject(index);

                    message = validate(APIConstants.REQUEST_CREATE, record, CommonUtil.getLong(routingContext.request().getParam(ID)), message);

                    if (!message.equalsIgnoreCase(EMPTY_VALUE))
                    {
                        records.remove(index);

                        // Log the invalid record with its index and message
                        LOGGER.warn(String.format("Invalid record at index %d: %s with message : %s", index, record.encodePrettily(), message));

                        message = EMPTY_VALUE; // Reset message for next record
                    }
                }

                if (records.isEmpty())
                {
                    // If all records are invalid, send a bad request response
                    message = String.format(ErrorMessageConstants.DEPENDENCY_MAPPER_FAILED, "All entries contains cyclic or duplicate dependencies");

                    LOGGER.warn(message);

                    routingContext.response().setStatusCode(HttpStatus.SC_BAD_REQUEST).end(new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(GlobalConstants.STATUS, STATUS_FAIL).put(GlobalConstants.MESSAGE, message).encode());

                    return;
                }

                Bootstrap.configDBService().saveAll(table, records, routingContext.user().principal().getString(User.USER_NAME), routingContext.request().remoteAddress().host(), result ->
                {
                    if (result.succeeded())
                    {
                        this.configStore.updateItems(result.result()).onComplete(asyncResult ->
                        {
                            var response = new JsonObject()
                                    .put(RESPONSE_CODE, HttpStatus.SC_OK)
                                    .put(GlobalConstants.STATUS, STATUS_SUCCEED)
                                    .put(GlobalConstants.MESSAGE, String.format(InfoMessageConstants.ENTITY_CREATED, schema.getString(APIConstants.ENTITY_NAME)))
                                    .put(ID, result.result());

                            this.afterCreate(response, routingContext);
                        });
                    }

                    else
                    {
                        this.send(routingContext, new JsonObject()
                                .put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR)
                                .put(GlobalConstants.STATUS, STATUS_FAIL)
                                .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.ENTITY_CREATE_FAILED, schema.getString(APIConstants.ENTITY_NAME), result.cause().getMessage()))
                                .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                .put(GlobalConstants.ERROR, CommonUtil.formatStackTrace(result.cause().getStackTrace())));
                    }
                });

            }
            else
            {
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL).put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.SCHEMA_FILE_NOT_FOUND, endpoint)));
            }
        }

        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    /**
     * Parses a CSV file containing dependency mapper records and populates the provided records array.
     *
     * <p>
     * The CSV file is expected to be located in the uploads directory and its name is provided in the
     * DEPENDENCY_MAPPER_FILE field of the body. Each row in the CSV (except the header) is validated
     * and, if valid and unique, converted into a JsonObject and added to the records array.
     * </p>
     *
     * <ul>
     *   <li>Skips rows that are invalid, duplicate, or exceed the probe limit.</li>
     *   <li>Logs warnings for missing interfaces or invalid data.</li>
     *   <li>Returns false and sends an error response if the file is missing, empty, or an exception occurs.</li>
     * </ul>
     *
     * @param body    the request body containing the CSV file name
     * @param records the JsonArray to populate with parsed records
     * @return empty string if parsing and validation succeed, error message otherwise
     */
    private static String parse(JsonObject body, JsonArray records)
    {
        try
        {
            var message = EMPTY_VALUE;

            var csvFile = CURRENT_DIR + PATH_SEPARATOR + UPLOADS + PATH_SEPARATOR + body.getString(DEPENDENCY_MAPPER_FILE);

            if (Bootstrap.vertx().fileSystem().existsBlocking(csvFile))
            {
                var content = CommonUtil.getString(Bootstrap.vertx().fileSystem().readFileBlocking(csvFile));

                if (CommonUtil.isNotNullOrEmpty(content))
                {
                    try (var reader = new CSVReader(new StringReader(content)))
                    {
                        var lines = reader.readAll();

                        var seen = new HashSet<>();

                        var probes = 0;

                        for (var index = 1; index < lines.size(); index++)
                        {
                            // Limit the number of probes to avoid performance issues
                            if (probes >= DEPENDENCY_MAPPER_CSV_MAX_PROBE_LIMIT) break;

                            var row = lines.get(index);

                            if (isValid(row))
                            {
                                var key = String.join(VALUE_SEPARATOR, row);

                                // Key to check for multiple parents for same child device (child + child_interface + layer)
                                var childKey = row[2] + VALUE_SEPARATOR + row[3] + VALUE_SEPARATOR + VALUE_SEPARATOR + row[4];

                                // Key to check for multiple children for same parent interface in L2 layer (parent + parent_interface + layer)
                                if (row[4].toLowerCase().equalsIgnoreCase(NMSConstants.State.DISABLE.name())
                                        && !seen.add(row[0] + VALUE_SEPARATOR + row[1] + VALUE_SEPARATOR + row[4]))
                                {
                                    LOGGER.warn(String.format("Skipping L2 dependency: Parent %s interface %s already has a child", row[0], row[1]));

                                    continue;
                                }

                                // Key to check for cyclic dependencies (parent + parent_interface + child + child_interface + layer)
                                if (seen.contains(row[2] + VALUE_SEPARATOR + row[3] + VALUE_SEPARATOR + row[0] + VALUE_SEPARATOR + row[1] + VALUE_SEPARATOR + row[4]))
                                {
                                    LOGGER.warn(String.format("Skipping cyclic dependency: %s <-> %s", row[0], row[2]));

                                    continue;
                                }

                                if (seen.add(key))
                                {
                                    if (seen.add(childKey))
                                    {
                                        var parentObjects = MetricConfigStore.getStore().getNetworkInterfacesBySource(row[0]);

                                        var childObjects = MetricConfigStore.getStore().getNetworkInterfacesBySource(row[2]);

                                        var parentInterfaceIndex = EMPTY_VALUE;

                                        var childInterfaceIndex = EMPTY_VALUE;

                                        if (parentObjects == null || childObjects == null )
                                        {
                                            LOGGER.warn(String.format("Skipping row as Parent or child interface index not found for row: %s", Arrays.toString(row)));

                                            continue; // Skip this row if interfaces are not found
                                        }

                                        // Find the parent interface index
                                        for (var i = 0; i < parentObjects.size(); i++)
                                        {
                                            var item = parentObjects.getJsonObject(i);

                                            // Check if the interface name matches the provided parent interface name
                                            if (item.getString(NMSConstants.INTERFACE_NAME).equalsIgnoreCase(row[1]))
                                            {
                                                parentInterfaceIndex = item.getString(NMSConstants.INTERFACE_INDEX);
                                            }
                                        }

                                        for (var i = 0; i < childObjects.size(); i++)
                                        {
                                            var item = childObjects.getJsonObject(i);

                                            // Check if the interface name matches the provided child interface name if given
                                            if (CommonUtil.isNotNullOrEmpty(row[3]) && item.getString(NMSConstants.INTERFACE_NAME).equalsIgnoreCase(row[3]))
                                            {
                                                childInterfaceIndex = item.getString(NMSConstants.INTERFACE_INDEX);
                                            }
                                        }

                                        if (CommonUtil.isNullOrEmpty(parentInterfaceIndex) || (CommonUtil.isNotNullOrEmpty(row[3]) && CommonUtil.isNullOrEmpty(childInterfaceIndex)))
                                        {
                                            LOGGER.warn(String.format("Skipping row as Parent or child interface index not found for row: %s", Arrays.toString(row)));

                                            continue; // Skip this row if interfaces are not found
                                        }

                                        records.add(new JsonObject().put(DEPENDENCY_MAPPER_TYPE, DependencyMapperType.NETWORK.getName())
                                                .put(DEPENDENCY_MAPPER_CHILD, row[2])
                                                .put(DEPENDENCY_MAPPER_PARENT, row[0])
                                                .put(DEPENDENCY_MAPPER_CONTEXT, new JsonObject()
                                                        .put(DEPENDENCY_MAPPER_LINK_LAYER, row[4].toLowerCase().equalsIgnoreCase(NMSConstants.State.ENABLE.name()) ? DependencyMapperLinkLayer.L3.getName() : DependencyMapperLinkLayer.L2.getName())
                                                        .put(DEPENDENCY_MAPPER_CHILD_INTERFACE_NAME, row[3])
                                                        .put(DEPENDENCY_MAPPER_PARENT_INTERFACE_NAME, row[1])
                                                        .put(DEPENDENCY_MAPPER_PARENT_INTERFACE, parentInterfaceIndex)
                                                        .put(DEPENDENCY_MAPPER_CHILD_INTERFACE, childInterfaceIndex)));

                                        probes++;
                                    }
                                    else  // Single child multiple parents warning
                                    {
                                        LOGGER.warn(String.format("Child %s (interface %s, layer %s) already has a parent", row[2], row[3], row[4]));
                                    }
                                }
                                else
                                {
                                    LOGGER.warn(String.format("Duplicate entry found: %s", Arrays.toString(row)));
                                }
                            }
                        }
                    }
                    catch (Exception exception)
                    {
                        message = exception.getMessage();

                        LOGGER.error(exception);
                    }
                }

                else
                {
                    message = String.format("%s %s with empty content", ErrorMessageConstants.API_INVALID_CSV_FILE, csvFile);

                    LOGGER.warn(message);
                }
            }

            else
            {
                message = String.format(ErrorMessageConstants.FILE_NOT_FOUND, csvFile);

                LOGGER.warn(message);
            }

            return message;
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);

            return exception.getMessage();
        }
    }

    /**
     * Validates a single row from the dependency mapper CSV import.
     *
     * <p>
     * Checks performed:
     * <ul>
     *   <li>Row must have exactly 5 columns.</li>
     *   <li>The link layer value (row[4]) must be either ENABLE or DISABLE (case-insensitive).</li>
     *   <li>All columns except the child interface (row[3]) must be non-null and non-empty.</li>
     *   <li>Parent and child devices (row[0] and row[2]) must exist in the object store.</li>
     *   <li>Parent device must be of NETWORK category.</li>
     *   <li>If a child interface is provided, both parent and child interfaces must be valid for their respective devices.</li>
     * </ul>
     * Logs warnings for invalid data and returns false if any check fails.
     *
     * @param row The CSV row as a String array.
     * @return true if the row is valid, false otherwise.
     */
    private static boolean isValid(String[] row)
    {
        try
        {
            if (row.length != 5 || !(NMSConstants.State.ENABLE.name().equalsIgnoreCase(row[4].toLowerCase()) || NMSConstants.State.DISABLE.name().equalsIgnoreCase(row[4].toLowerCase())))
            {
                LOGGER.warn(String.format("Invalid row length or link layer value: %s", Arrays.toString(row)));

                return false;
            }

            for (var index = 0; index < 5; index++)
            {
                if (CommonUtil.isNullOrEmpty(row[index]) && index != 3) // childObject interface ( row[3] ) can be empty
                {
                    LOGGER.warn(String.format("Null or empty row[%d] value: %s", index, Arrays.toString(row)));

                    return false;
                }
            }

            // Validate L3 dependencies must have child interface
            if (row[4].toLowerCase().equalsIgnoreCase(NMSConstants.State.ENABLE.name()) && CommonUtil.isNullOrEmpty(row[3]))
            {
                LOGGER.warn(String.format("Missing child interface for L3-enabled entry: %s", Arrays.toString(row)));

                return false;
            }

            // Valid Parent and Child Device
            var parentId = ObjectConfigStore.getStore().getItemByIP(row[0]);

            var childId = ObjectConfigStore.getStore().getItemByIP(row[2]);

            if (parentId == null || childId == null)
            {
                LOGGER.warn(String.format("Either Parent Monitor or Child Monitor is not present for row: %s", Arrays.toString(row)));

                return false;
            }

            else if (!ObjectConfigStore.getStore().getItem(parentId).getString("object.category").equalsIgnoreCase(NMSConstants.Category.NETWORK.getName()))
            {
                LOGGER.warn(String.format("Parent Monitor is not a network device for row: %s", Arrays.toString(row)));

                return false;
            }

            return true;
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);

            return false;
        }
    }

    public enum DependencyMapperType
    {
        NETWORK("Network"),

        APPLICATION("Application");

        private static final Map<String, DependencyMapperType> VALUES = Collections.unmodifiableMap(Arrays.stream(values())
                .collect(Collectors.toMap(DependencyMapperType::getName, e -> e)));
        private final String name;

        DependencyMapperType(String name)
        {
            this.name = name;
        }

        public static DependencyMapperType valueOfName(String name)
        {
            return VALUES.get(name);
        }

        public String getName()
        {
            return name;
        }
    }

    // for application dependency mapper we will introduce link layer later
    public enum DependencyMapperLinkLayer
    {
        L2("L2"),

        L3("L3");

        private static final Map<String, DependencyMapperLinkLayer> VALUES = Collections.unmodifiableMap(Arrays.stream(values())
                .collect(Collectors.toMap(DependencyMapperLinkLayer::getName, e -> e)));
        private final String name;

        DependencyMapperLinkLayer(String name)
        {
            this.name = name;
        }

        public static DependencyMapperLinkLayer valueOfName(String name)
        {
            return VALUES.get(name);
        }

        public String getName()
        {
            return name;
        }
    }
