import io.vertx.ext.web.RoutingContext;
import org.apache.http.HttpStatus;

import java.util.HashSet;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.*;
import static com.mindarray.api.User.USER_NAME;
import static org.apache.http.HttpStatus.SC_BAD_REQUEST;
import static org.apache.http.HttpStatus.SC_OK;

public class Rebranding extends AbstractAPI
{
    public static final String REBRANDING_LOGO = "rebranding.logo";
    public static final String REBRANDING_LOGO_NAME = "rebranding.logo.name";

    public static final String REBRANDING_DARK_LOGO_NAME = "rebranding.dark.logo.name";

    private static final Logger LOGGER = new Logger(Rebranding.class, MOTADATA_API, "Rebranding API");

    public Rebranding()
    {
        super("rebranding", RebrandingConfigStore.getStore(), new Logger(Rebranding.class, MOTADATA_API, "Rebranding API"));
    }

    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router, new HashSet<>()
            {{
                add(REQUEST_UPDATE);
                add(REQUEST_GET);
            }});

            router.put("/" + endpoint + "/:id").handler(this::validate).handler(this::update); // no need to bind separate endpoint use abstract API endpoint with default id...need to discuss with drashti for a change in UI also
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    protected void update(RoutingContext routingContext)
    {
        try
        {
            var schema = CommonUtil.getEntitySchema(endpoint);

            if (schema != null)
            {
                var item = routingContext.body().asJsonObject();

                var id = CommonUtil.getLong(routingContext.request().getParam(GlobalConstants.ID));

                Bootstrap.configDBService().update(schema.getString(APIConstants.ENTITY_COLLECTION),
                        new JsonObject().put(ConfigDBConstants.FIELD_NAME, ID).put(VALUE, id),
                        item,
                        routingContext.user().principal().getString(USER_NAME),
                        routingContext.request().remoteAddress().host(),
                        result ->
                        {
                            if (result.succeeded())
                            {
                                RebrandingConfigStore.getStore().updateItem(id).onComplete(future -> this.send(routingContext, new JsonObject().put(RESPONSE_CODE, SC_OK).put(STATUS, STATUS_SUCCEED).put(RESULT, item).put(ID, id)));
                            }
                            else
                            {
                                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, SC_BAD_REQUEST).put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                        .put(MESSAGE, String.format(ErrorMessageConstants.ENTITY_UPDATE_FAILED, schema.getString(APIConstants.ENTITY_NAME), result.cause()))
                                        .put(STATUS, STATUS_FAIL));
                            }
                        });
            }
            else
            {
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                        .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.SCHEMA_FILE_NOT_FOUND, endpoint)));
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }
}

