package com.mindarray.patch;


import com.mindarray.Bootstrap;
import com.mindarray.db.DBConstants;
import com.mindarray.notification.Notification;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.util.Logger;
import com.unboundid.util.json.JSONArray;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.GlobalConstants.SYSTEM_REMOTE_ADDRESS;
import static com.mindarray.nms.NMSConstants.*;


public class Patch811 implements Patch
{

    private static final Logger LOGGER = new Logger(Patch810.class, MOTADATA_PATCH, "Patch 8.1.1");

    private static final String VERSION = "8.1.1";



    /**
     * Returns the version number of this patch.
     *
     * @return The version string "8.1.1"
     */
    @Override
    public String getVersion()
    {
        return VERSION;
    }

    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("executing 8.1.1 patch...");

            var futures = new ArrayList<Future<Void>>();

            futures.add(updateObjectNotificationContext());

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully executed 8.1.1 patch");

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }


    // While bulk notification now we have different json structure which support rich notification like channel
    // so we will change json structure here like the policy context
    private Future<Void> updateObjectNotificationContext()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var items = ObjectConfigStore.getStore().getItems();

            for (var index = 0; index < items.size(); index++)
            {
                var object = items.getJsonObject(index);

                if (object != null && object.containsKey(OBJECT_MONITOR_POLLING_FAILED_NOTIFICATION_STATUS) && object.getString(OBJECT_MONITOR_POLLING_FAILED_NOTIFICATION_STATUS).equalsIgnoreCase(YES))
                {
                    var notificationContext = new JsonObject().put(Notification.NotificationType.EMAIL.getName(),new JSONArray());

                    // we will only patch support the emails as for sms we need users and there is no guarantee there will be users available.
                    // discussed with PMG
                    if (object.getValue(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS) != null)
                    {
                        notificationContext.getJsonArray(Notification.NotificationType.EMAIL.getName()).addAll(object.getJsonArray(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS));
                    }

                    object.put(OBJECT_NOTIFICATION,notificationContext);

                    object.remove(OBJECT_EMAIL_NOTIFICATION_RECIPIENTS);

                    object.remove(OBJECT_SMS_NOTIFICATION_RECIPIENTS);

                }
            }

            Bootstrap.configDBService().upsertAll(DBConstants.TBL_OBJECT, items, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully migrated all objects");

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });

            promise.complete();
        }
        catch (Exception e)
        {
            LOGGER.error(e);

            promise.fail(e);
        }

        return promise.future();

    }

}

