    private AgentConstants()
    {
    }

    /**
     * Updates metrics based on agent status changes.
     * <p>
     * This method compares the old and new metric agent status. If the status has changed
     * (enabled to disabled or vice versa), it enables or disables all metrics associated
     * with the agent except for availability metrics.
     * <p>
     * The method performs the following steps:
     * <ol>
     *   <li>Extracts the new metric agent status from the event</li>
     *   <li>Compares it with the current status stored in the agent configuration</li>
     *   <li>If different, retrieves all metrics associated with the agent's object</li>
     *   <li>Filters out availability metrics (which are always kept enabled)</li>
     *   <li>Sends enable/disable events for each metric based on the new status</li>
     * </ol>
     *
     * @param event The event containing agent configuration changes
     */
    public static void updateMetric(JsonObject event)
    {
        var id = AgentConfigStore.getStore().getAgentId(event.getString(AGENT_UUID));

        // Extract the new metric agent status from the event
        var status = new JsonObject(event.getString(AGENT_CONFIGS)).getJsonObject(AGENT)
                .getString(METRIC_AGENT_STATUS);

        // Compare old and new metric agent state and if state is different,
        // enable/disable metrics (except availability) based on new state
        if (!status.equalsIgnoreCase(new JsonObject(AgentConfigStore.getStore().getItem(id)
                .getString(AGENT_CONFIGS)).getJsonObject(AGENT)
                .getString(METRIC_AGENT_STATUS)))
        {
            // Get all metrics associated with the agent's object, excluding availability metrics
            MetricConfigStore.getStore().getItemsByObject(ObjectConfigStore.getStore().getItemByAgentId(id).getLong(ID))
                    .stream().filter(item -> !item.getString(Metric.METRIC_PLUGIN).equalsIgnoreCase(NMSConstants.MetricPlugin.AVAILABILITY.getName()))
                    .forEach(item -> Bootstrap.vertx().eventBus().send(
                            // Send enable or disable event based on the new status
                            status.equalsIgnoreCase(YES) ? EVENT_METRIC_ENABLE : EVENT_METRIC_DISABLE,
                            // Create event with metric ID and user information
                            new JsonObject()
                                    .put(EventBusConstants.EVENT_COPY_REQUIRED, false)
                                    .put(ID, id)
                                    .put(DEFAULT_USER, event.containsKey(USER_NAME) ? event.getString(USER_NAME) : DEFAULT_USER)));
        }
    }

    /**
     * Enumeration of agent types supported by the Motadata system.
     * <p>
     * Each agent type represents a different data collection mechanism:
     * <ul>
     *   <li>METRIC - Collects performance metrics from systems</li>
     *   <li>LOG - Collects and processes log data</li>
     *   <li>WINDOWS_EVENT_LOG - Collects Windows event log data</li>
     *   <li>PACKET - Collects network packet data</li>
     * </ul>
     */
    public enum Agent
    {
        /**
         * Agent type for collecting performance metrics from systems
         */
        METRIC("metric"),

        /**
         * Agent type for collecting and processing log data
         */
        LOG("log"),

        /**
         * Agent type for collecting Windows event log data
         */
        WINDOWS_EVENT_LOG("windows.event.log"),

        /**
         * Agent type for collecting network packet data
         */
        PACKET("packet"),

        TRACE("trace");

        /**
         * Map for efficient lookup of enum values by name
         */
        private static final Map<String, Agent> VALUES = Collections.unmodifiableMap(Arrays.stream(values())
                .collect(Collectors.toMap(Agent::getName, e -> e)));

        /**
         * The string name of the agent type
         */
        private final String name;

        /**
         * Constructor for Agent enum.
         *
         * @param name The string name of the agent type
         */
        Agent(String name)
        {
            this.name = name;
        }

        /**
         * Gets an Agent enum value by its string name.
         *
         * @param name The string name to look up
         * @return The corresponding Agent enum value, or null if not found
         */
        public static Agent valueOfName(String name)
        {
            return VALUES.get(name);
        }

        /**
         * Gets the string name of this agent type.
         *
         * @return The string name
         */
        public String getName()
        {
            return name;
        }
    }

    /**
     * Enumeration of agent status monitoring types.
     * <p>
     * Defines the different mechanisms used to monitor agent health:
     * <ul>
     *   <li>HEARTBEAT - Agent actively sends heartbeat signals to the server</li>
     *   <li>PING - Server pings the agent to check its availability</li>
     * </ul>
     */
    public enum AgentStatusType
    {
        /**
         * Status monitoring via agent-initiated heartbeat signals
         */
        HEARTBEAT("Heartbeat"),

        /**
         * Status monitoring via server-initiated ping requests
         */
        PING("Ping");

        /**
         * Map for efficient lookup of enum values by name
         */
        private static final Map<String, AgentStatusType> VALUES = Collections.unmodifiableMap(Arrays.stream(values())
                .collect(Collectors.toMap(AgentStatusType::getName, e -> e)));

        /**
         * The string name of the status type
         */
        private final String name;

        /**
         * Constructor for AgentStatusType enum.
         *
         * @param name The string name of the status type
         */
        AgentStatusType(String name)
        {
            this.name = name;
        }

        /**
         * Gets an AgentStatusType enum value by its string name.
         *
         * @param name The string name to look up
         * @return The corresponding AgentStatusType enum value, or null if not found
         */
        public static AgentStatusType valueOfName(String name)
        {
            return VALUES.get(name);
        }

        /**
         * Gets the string name of this status type.
         *
         * @return The string name
         */
        public String getName()
        {
            return name;
        }
    }

    /**
     * Publishes an event to the appropriate event bus topic based on its content and type.
     * <p>
     * This method performs the following actions:
     * <ul>
     *     <li>Validates that the event contains required fields: {@code EVENT_TYPE} and {@code AGENT_UUID}.</li>
     *     <li>Generates and adds a unique {@code EVENT_ID} to the event.</li>
     *     <li>If the {@code AGENT_DISABLE} flag is present, updates the agent's state and duration in the cache,
     *         and sends a UI notification regarding the agent action.</li>
     *     <li>Constructs a context object and sends it to the {@code EVENT_ADD} topic.</li>
     *     <li>Depending on the {@code EVENT_TOPIC} value, publishes the event to the correct bus channel.</li>
     *     <li>Logs a warning if required fields are missing, and logs an error on any exceptions thrown.</li>
     * </ul>
     *
     * @param event  the JSON event object to be published. Must contain at least {@code EVENT_TYPE} and {@code AGENT_UUID}.
     * @param logger the logger used for logging warnings and errors during processing.
     */
    public static void publishEvent(JsonObject event, Logger logger)
    {
        try
        {
            event.put(HOST, Bootstrap.getIPAddress());

            if (!event.isEmpty() && isNotNullOrEmpty(event.getString(EVENT_TYPE)) && isNotNullOrEmpty(event.getString(AGENT_UUID)))
            {
                event.put(EVENT_ID, CommonUtil.newEventId());

                if (CommonUtil.isNotNullOrEmpty(event.getString(AGENT_DISABLE))) //improvements - 3636 -> prevent user to perform any action
                {
                    AgentCacheStore.getStore().updateItem(event.getLong(ID), AgentCacheStore.getStore().getItem(event.getLong(ID)).put(AGENT_DISABLE, event.getString(AGENT_DISABLE)));

                    AgentCacheStore.getStore().updateDuration(event.getLong(ID), event.getString(AGENT_DISABLE));

                    EventBusConstants.publish(UI_NOTIFICATION_AGENT, new JsonObject().put(EVENT_TYPE, EVENT_AGENT_ACTION).put(ID, event.getLong(ID))
                            .put(AGENT_UUID, event.getString(AGENT_UUID)).put(AGENT_DISABLE, event.getString(AGENT_DISABLE)));
                }

                var context = new JsonObject().put(EventBusConstants.EVENT_CONTEXT, event)
                        .put(EventBusConstants.EVENT_ID, event.getLong(EVENT_ID))
                        .put(USER_NAME, event.remove(USER_NAME))
                        .put(EventBusConstants.EVENT_TYPE, event.getString(EVENT_TYPE));

                if (event.getString(UI_EVENT_UUID) != null)
                {
                    context.put(UI_EVENT_UUID, event.getString(UI_EVENT_UUID));
                }

                Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_ADD, context);

                if (AGENT_TOPIC.equalsIgnoreCase(event.getString(EVENT_TOPIC)))
                {
                    Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_PUBLICATION, event);
                }
                else if (MOTADATA_MANAGER_TOPIC.equalsIgnoreCase(event.getString(EVENT_TOPIC)))
                {
                    Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_PUBLICATION_MOTADATA_MANAGER, event);
                }
            }
            else
            {
                logger.warn(String.format("failed to send event %s", event));
            }
        }
        catch (Exception exception)
        {
            logger.error(exception);
        }
    }

    /**
     * Writes the given properties from a {@link JsonObject} to a file in `.properties` format.
     * <p>
     * This method performs the following operations:
     * <ul>
     *     <li>Extracts service trace attributes and writes them as a single entry under {@code OTEL_RESOURCE_ATTRIBUTES},
     *         formatting the JSON object as a string without curly braces.</li>
     *     <li>Extracts custom trace attributes and writes each key-value pair individually.</li>
     *     <li>Removes both service and custom trace attributes from the main property map to avoid duplication.</li>
     *     <li>Writes remaining attributes from the original JSON object to the property file.</li>
     *     <li>Logs any exceptions that occur during file writing.</li>
     * </ul>
     *
     * @param path     the file system path where the property file will be written.
     * @param property the {@link JsonObject} containing configuration data to be dumped to the file.
     * @param logger   the logger used to log errors encountered during the file operation.
     */
    public static void dumpPropertyFile(String path, JsonObject property, Logger logger)
    {
        try (var writer = new FileWriter(path))
        {
            var properties = new Properties();

            var attributes = property.getMap();

            if (attributes.containsKey(TraceConstants.SERVICE_TRACE_ATTRIBUTES) && property.getJsonObject(TraceConstants.SERVICE_TRACE_ATTRIBUTES).size() > 0)
            {
                properties.put(TraceConstants.OTEL_RESOURCE_ATTRIBUTES, attributes.get(TraceConstants.SERVICE_TRACE_ATTRIBUTES).toString().replaceAll("[{}]", EMPTY_VALUE));
            }

            if (attributes.containsKey(TraceConstants.CUSTOM_TRACE_ATTRIBUTES) && property.getJsonObject(TraceConstants.CUSTOM_TRACE_ATTRIBUTES).size() > 0)
            {
                property.getJsonObject(TraceConstants.CUSTOM_TRACE_ATTRIBUTES).getMap().forEach((key, value) -> properties.put(key, CommonUtil.getString(value)));
            }

            if (!TraceConstants.AgentType.JAVA.name().equalsIgnoreCase(CommonUtil.getString(attributes.get(TraceConstants.SERVICE_TYPE))))
            {
                attributes.put("otel.metrics.exporter", "none");
            }

            if (attributes.containsKey(TraceConstants.SERVICE_DEPLOYMENT_TYPE) &&
                    "DOCKER".equalsIgnoreCase(CommonUtil.getString(attributes.get(TraceConstants.SERVICE_DEPLOYMENT_TYPE))))
            {
                attributes.put("otel.exporter.otlp.endpoint", "http://host.docker.internal:4318");
            }

            //change to PYTHON, done NODE_JS only for testing
            if("NODEJS".equalsIgnoreCase(CommonUtil.getString(attributes.get(TraceConstants.SERVICE_TYPE))))
            {
                attributes.put("otel.exporter.otlp.protocol", "http/protobuf");
            }

            attributes.remove(TraceConstants.SERVICE_TRACE_ATTRIBUTES);

            attributes.remove(TraceConstants.CUSTOM_TRACE_ATTRIBUTES);

            attributes.forEach((key, value) -> properties.put(key, CommonUtil.getString(value)));

            properties.store(writer, null);
        }
        catch (Exception exception)
        {
            logger.error(exception);
        }
    }
