package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.ha.HAConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.File;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.ha.HAConstants.CACHE_NAME;
import static com.mindarray.ha.HAConstants.HA_SYNC_OPERATION;

public class ObserverDatastore extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(ObserverDatastore.class, MOTADATA_DATASTORE, "Observer Datastore Manager");

    private DatastoreEngine eventEngine;
    private String uuid;

    private String path;

    public ObserverDatastore()
    {

    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            uuid = config().getString(EventBusConstants.EVENT_TYPE).split(DOT_SEPARATOR_ESCAPE)[3];

            path = CURRENT_DIR + PATH_SEPARATOR + EVENT_DIR + PATH_SEPARATOR + uuid;

            vertx.eventBus().<JsonObject>localConsumer(EVENT_HA_CACHE_MANAGER_SYNC + "." + uuid, message ->
            {
                var event = message.body();

                switch (HAConstants.HASyncOperation.valueOfName(CommonUtil.getByteValue(event.getValue(HA_SYNC_OPERATION))))
                {
                    case WRITE ->
                    {
                        try
                        {
                            var router = event.getLong(EVENT_TIMESTAMP) % MotadataConfigUtil.getConfigDBWorkerInstances();

                            LOGGER.info(String.format("received updated cache file %s ", event.getString(CACHE_NAME)));

                            Bootstrap.vertx().fileSystem().writeFileBlocking(path + DASH_SEPARATOR + router + PATH_SEPARATOR + event.getString(CACHE_NAME), Buffer.buffer(event.getBinary(RESULT)));
                        }
                        catch (Exception exception)
                        {
                            LOGGER.error(exception);
                        }
                    }

                    case READ ->
                    {
                        for (var eventRouter = 0; eventRouter < MotadataConfigUtil.getConfigDBWorkerInstances(); eventRouter++)
                        {
                            var caches = new File(path + DASH_SEPARATOR + eventRouter).listFiles();

                            if (caches != null)
                            {
                                for (var cache : caches)
                                {
                                    if (!cache.getName().contains("bookmarks") && !cache.getName().endsWith(".dat"))
                                    {
                                        var bytes = vertx.fileSystem().readFileBlocking(path + DASH_SEPARATOR + eventRouter + PATH_SEPARATOR + cache.getName());

                                        vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER, new JsonObject()
                                                .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC)
                                                .put(EVENT_COPY_REQUIRED, false)
                                                .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                                .put(EVENT_TYPE, EVENT_HA_CACHE_OBSERVER_SYNC)
                                                .put(HA_SYNC_OPERATION, HAConstants.HASyncOperation.READ.getName())
                                                .put(CACHE_NAME, cache.getName())
                                                .put(RESULT, bytes));

                                        if (CommonUtil.debugEnabled())
                                        {
                                            LOGGER.debug(String.format("cache %s , size %s bytes , read by uuid %s ", cache.getName(), bytes.length(), event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)));
                                        }

                                        vertx.fileSystem().deleteBlocking(path + DASH_SEPARATOR + eventRouter + PATH_SEPARATOR + cache.getName());
                                    }
                                }
                            }
                        }
                    }
                }
            });

            eventEngine = new DatastoreEngine().setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                    .setPersistEventOffset(true).setRemoteStatus(false).setPause(true).setLogger(LOGGER).setEventHandler(this::send).start(vertx, promise);

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    private void send(JsonObject event)
    {
        vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER, event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,uuid).put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC).put(EVENT_TYPE, EVENT_HA_OBSERVER));

        LOGGER.trace(String.format("event sent to publication motadata observer %s ",uuid));
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            if (eventEngine != null)
            {
                eventEngine.stop(vertx,promise);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}


