package com.mindarray.policy;

import com.mindarray.GlobalConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.MetricPolicyCacheStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import static com.mindarray.GlobalConstants.SEVERITY;
import static com.mindarray.api.APIConstants.SESSION_ID;
import static com.mindarray.eventbus.EventBusConstants.publish;

public class SeverityChangeManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(SeverityChangeManager.class, GlobalConstants.MOTADATA_POLICY, "Severity Change Manager");

    private static final Map<String, JsonObject> severityChangesBySessionId = new HashMap<>();

    private static final Map<String, Long> sessionIdsByTimestamp = new HashMap<>();

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.UI_NOTIFICATION_SEVERITY_INIT, message ->
        {
            var event = message.body();

            try
            {
                var sessionId = event.getString(SESSION_ID);

                sessionIdsByTimestamp.put(sessionId, System.currentTimeMillis());

                // severity
                severityChangesBySessionId.put(sessionId, new JsonObject());

                publish(sessionId, EventBusConstants.UI_NOTIFICATION_SEVERITY_INIT, MetricPolicyCacheStore.getStore().getSeverities());
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.SEVERITY_CHANGE, message->
        {
            var event = message.body();

            try
            {
                severityChangesBySessionId.forEach((key, value)->
                        value.put(event.getString(PolicyEngineConstants.POLICY_KEY),
                                new JsonObject().put(event.getString(PolicyEngineConstants.POLICY_KEY), event.getString(SEVERITY)).put("severity.type", event.getString("severity.type"))));
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.UI_HEARTBEAT, message->
        {
            var event = message.body();

            try
            {
                var sessionId = event.getString(SESSION_ID);

                sessionIdsByTimestamp.put(sessionId, System.currentTimeMillis());

                severityChangesBySessionId.computeIfAbsent(sessionId, value -> new JsonObject());

                if (!severityChangesBySessionId.get(sessionId).isEmpty())
                {
                    var iterator = severityChangesBySessionId.get(sessionId).iterator();

                    var response = new JsonObject();

                    while (iterator.hasNext())
                    {
                        var severity = JsonObject.mapFrom(iterator.next().getValue());

                        var severityType = CommonUtil.getString(severity.remove("severity.type"));

                        if (severityType != null)
                        {
                            if (response.containsKey(severityType))
                            {
                                response.getJsonObject(severityType).mergeIn(severity);
                            }
                            else
                            {
                                response.put(severityType, new JsonObject().mergeIn(severity));
                            }
                        }
                    }

                    EventBusConstants.publish(sessionId, EventBusConstants.UI_NOTIFICATION_SEVERITY_INIT, response);

                    severityChangesBySessionId.get(sessionId).clear();
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.setPeriodic(TimeUnit.MINUTES.toMillis(MotadataConfigUtil.getUISessionTimeoutMinutes()), handler->
        {
            var iterator = sessionIdsByTimestamp.entrySet().iterator();

            while (iterator.hasNext())
            {
                var entry = iterator.next();

                if (entry.getValue() < System.currentTimeMillis() - TimeUnit.MINUTES.toMillis(5)) // user is inactive for more than 5 minutes
                {
                    LOGGER.debug("removing " + entry.getKey());

                    severityChangesBySessionId.remove(entry.getKey());

                    iterator.remove();
                }
            }
        });

        promise.complete();
    }
}
