    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(10)
    void testTelnetClientManagerEmptyCommand(VertxTestContext testContext)
    {
        var context = new JsonObject();

        // Find a configuration item that has a valid credential profile
        JsonObject item = null;

        var items = ConfigurationConfigStore.getStore().getItems();

        for (var configItem : items)
        {
            var jsonItem = (JsonObject) configItem;

            if (jsonItem.containsKey(Configuration.CONFIG_CREDENTIAL_PROFILE))
            {
                var credProfile = CredentialProfileConfigStore.getStore().getItem(jsonItem.getLong(Configuration.CONFIG_CREDENTIAL_PROFILE));

                if (credProfile != null)  // Has valid credential profile
                {
                    item = jsonItem;
                    LOGGER.info(String.format("testTelnetClientManagerEmptyCommand - Found device: ID=%s, Name=%s, CredProfile=%s",
                        item.getLong(ID), item.getString(AIOpsObject.OBJECT_NAME), credProfile.encodePrettily()));
                    break;
                }
            }
        }

        if (item != null)
        {
            var object = ObjectConfigStore.getStore().getItemByValue(AIOpsObject.OBJECT_NAME, item.getString(AIOpsObject.OBJECT_NAME));

            var credentialProfile = item.containsKey(Configuration.CONFIG_CREDENTIAL_PROFILE)
                ? CredentialProfileConfigStore.getStore().getItem(item.getLong(Configuration.CONFIG_CREDENTIAL_PROFILE), false)
                : null;

            var configContext = item.getJsonObject(Configuration.CONFIG_CONTEXT);

            var originalProtocol = credentialProfile != null ? credentialProfile.getString(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL) : null;

