                Assertions.assertNotNull(credentialProfile);

                credentialProfile.put(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL, NMSConstants.Protocol.TELNET.getName()).put(PORT, 23);

                if (configContext != null)
