                    }
                    else if (event.containsKey(SSH_OPERATION) && event.getString(SSH_OPERATION).equals(ConfigConstants.ClientOperation.CLOSE.getName()))
                    {

                        LOGGER.info("Telnet close event detected.");

                        try
                        {
