                                if (configContext != null && originalConfigContextProtocol != null)
                                {
                                    configContext.put(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL, originalConfigContextProtocol);
                                    configContext.remove(ConfigConstants.CONFIG_PORT);
                                    configContext.remove(PORT);
                                }

                                if (asyncResult.succeeded())
                                {
                                    LOGGER.info("Consumer unregistered successfully after close.");

                                    testContext.completeNow();
                                }
                                else
                                {
                                    LOGGER.warn(String.format("Failed to unregister consumer: %s", asyncResult.cause().getMessage()));

                                    testContext.failNow(asyncResult.cause());
                                }
                            });
                        }
                        catch (Exception exception)
                        {
                            LOGGER.warn(String.format("Assertion failed during close validation: %s", exception.getMessage()));

                            // Restore protocol before failing
                            if (originalProtocol != null)
                            {
                                credentialProfile.put(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL, originalProtocol);
                                credentialProfile.remove(PORT);
                            }

                            if (configContext != null && originalConfigContextProtocol != null)
                            {
                                configContext.put(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL, originalConfigContextProtocol);
                                configContext.remove(ConfigConstants.CONFIG_PORT);
                                configContext.remove(PORT);
                            }

                            testContext.failNow(exception);
                        }
                    }
                    else
                    {
                        LOGGER.warn(String.format("Unexpected event structure or operation: %s", event.encodePrettily()));
                    }
                });

                // Send the Telnet connection request
                TestUtil.vertx().eventBus().send(EVENT_SSH_CLIENT_MANAGER, context);
            }
            catch (Exception exception)
            {
                // Restore original protocol in case of exception
                if (credentialProfile != null && originalProtocol != null)
                {
                    credentialProfile.put(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL, originalProtocol);
                    credentialProfile.remove(PORT);
                }

                if (configContext != null && originalConfigContextProtocol != null)
                {
                    configContext.put(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL, originalConfigContextProtocol);
                    configContext.remove(ConfigConstants.CONFIG_PORT);
                    configContext.remove(PORT);
                }

                testContext.failNow(exception);
            }
        }
        else
        {
            LOGGER.warn("No Config device Present");

            Assertions.fail("No configuration device found.");
        }
